import{r as e}from"./framework-DjPHiq1u.js";import t from"./image-DISDkL5R.js";import n from"./link-WUM60vzj.js";import{i as r,n as i,t as a}from"./site-header-BvWuGez_.js";var o=e(),s={en:[`About`,`Contact`,`Privacy`,`Terms`],es:[`Acerca de`,`Contacto`,`Privacidad`,`Términos`],de:[`Über uns`,`Kontakt`,`Datenschutz`,`Bedingungen`],fr:[`À propos`,`Contact`,`Confidentialité`,`Conditions`],it:[`Chi siamo`,`Contatti`,`Privacy`,`Termini`]};function c({locale:e=`en`}){let c=a[e],l=i[e],u=[{label:l.workflow,href:`/how-it-works`},{label:l.qc,href:`/guides/qc`},{label:l.shipping,href:`/guides/shipping`},{label:l.faq,href:`/faq`}],d=[{label:s[e][0],href:`/about`},{label:s[e][1],href:`/contact`},{label:s[e][2],href:`/privacy`},{label:s[e][3],href:`/terms`}];return(0,o.jsxs)(`footer`,{className:`site-footer`,children:[(0,o.jsxs)(`div`,{className:`footer-lead`,children:[(0,o.jsx)(n,{className:`wordmark footer-wordmark`,href:r(`/`,e),"aria-label":`Lolobuy Sheet home`,children:(0,o.jsx)(t,{className:`brand-logo footer-brand-logo`,src:`/lolobuy-logo.png`,alt:`LoloBuy`,width:127,height:29,unoptimized:!0})}),(0,o.jsx)(`p`,{children:c.lead})]}),(0,o.jsxs)(`div`,{className:`footer-column`,children:[(0,o.jsx)(`p`,{children:c.guides}),u.map(t=>(0,o.jsx)(n,{href:r(t.href,e),children:t.label},t.href))]}),(0,o.jsxs)(`div`,{className:`footer-column`,children:[(0,o.jsx)(`p`,{children:c.site}),d.map(t=>(0,o.jsx)(n,{href:r(t.href,e),children:t.label},t.href))]}),(0,o.jsxs)(`div`,{className:`footer-column footer-external`,children:[(0,o.jsx)(`p`,{children:c.directory}),(0,o.jsxs)(`a`,{href:`https://www.cnbuycha.com/AllProducts/`,target:`_blank`,rel:`noopener`,children:[c.directoryLink,` ↗`]}),(0,o.jsx)(`span`,{children:c.verify})]}),(0,o.jsxs)(`div`,{className:`footer-bottom`,children:[(0,o.jsx)(`span`,{children:`© 2026 Lolobuy Sheet`}),(0,o.jsx)(`span`,{children:c.imageNote})]})]})}var l=`https://www.cnbuycha.com`,u=[{slug:`snow-ski-goggles`,name:`Snow ski goggles`,image:`https://www.cnbuycha.com/uploads/allimg/20260722/1-260H2211J0L9.webp`,destinationHref:`${l}/AllProducts/3372.html`,listingReference:`3372`,kind:`eyewear`,category:`Eyewear`,tags:[`all`,`new`,`trending`],description:`A visual product-directory entry for snow ski goggles. Use the current listing to confirm the selected lens, frame option, included pieces and current availability before ordering.`},{slug:`gucci-hat`,name:`Gucci hat`,image:`https://www.cnbuycha.com/uploads/allimg/20260722/1-260H221155C13.webp`,destinationHref:`${l}/AllProducts/3371.html`,listingReference:`3371`,kind:`headwear`,category:`Headwear`,tags:[`all`,`new`,`essential`],description:`A visual product-directory entry for a Gucci-labelled hat. Confirm the exact option, dimensions, construction details and live listing information rather than relying on the directory image alone.`},{slug:`off-white-hoodies`,name:`Off-White hoodies`,image:`https://www.cnbuycha.com/uploads/allimg/20260722/1-260H2211102W7.webp`,destinationHref:`${l}/AllProducts/3369.html`,listingReference:`3369`,kind:`hoodie`,category:`Hoodies & sweaters`,tags:[`all`,`trending`,`essential`],description:`A visual product-directory entry for Off-White-labelled hoodies. Check the chosen design, garment measurements, print placement and live variant information before making a decision.`},{slug:`numeris-high-top-shoes`,name:`Numeris high-top shoes`,image:`https://www.cnbuycha.com/uploads/allimg/20260722/1-260H2210I0623.webp`,destinationHref:`${l}/AllProducts/3367.html`,listingReference:`3367`,kind:`shoes`,category:`Shoes`,tags:[`all`,`new`,`trending`],description:`A visual product-directory entry for Numeris high-top shoes. Verify the selected size and color, then use measurements and warehouse photos to check the pair that actually arrives.`},{slug:`hoka-speedgoat-5`,name:`HOKA Speedgoat 5`,image:`https://www.cnbuycha.com/uploads/allimg/20260713/1-260G31AHDQ.webp`,destinationHref:`${l}/AllProducts/3359.html`,listingReference:`3359`,kind:`shoes`,category:`Shoes`,tags:[`all`,`new`,`trending`],description:`A visual product-directory entry for a HOKA Speedgoat 5-labelled shoe. Confirm the current option, size information and listing details, then compare both shoes during warehouse QC.`},{slug:`nike-elite-backpack`,name:`Nike Elite backpack`,image:`https://www.cnbuycha.com/uploads/allimg/20260706/1-260F6161259202.webp`,destinationHref:`${l}/AllProducts/3346.html`,listingReference:`3346`,kind:`bag`,category:`Bags`,tags:[`all`,`trending`,`essential`],description:`A visual product-directory entry for a Nike Elite-labelled backpack. Confirm dimensions, compartments, straps, closures and the chosen color on the current listing before ordering.`},{slug:`balenciaga-puffer`,name:`Balenciaga puffer`,image:`https://www.cnbuycha.com/uploads/allimg/20260706/1-260F6160550120.webp`,destinationHref:`${l}/AllProducts/3343.html`,listingReference:`3343`,kind:`jacket`,category:`Outerwear`,tags:[`all`,`trending`],description:`A visual product-directory entry for a Balenciaga-labelled puffer jacket. Compare garment measurements, closures, panel alignment and fill distribution before accepting the warehouse arrival.`},{slug:`winter-hooded-jacket`,name:`Winter hooded jacket`,image:`https://www.cnbuycha.com/uploads/allimg/20260701/1-260F115520U91.webp`,destinationHref:`${l}/AllProducts/3341.html`,listingReference:`3341`,kind:`jacket`,category:`Outerwear`,tags:[`all`,`trending`,`essential`],description:`A visual product-directory entry for a winter hooded jacket. Check the selected size and color, garment measurements, hood, closures, pockets and visible construction before shipping.`}];`${l}`,`${l}`,`${l}`,`${l}`,`${l}`,`${l}`,`${l}`,`${l}`;var d=[{slug:`lolobuy-spreadsheet-guide`,title:`Lolobuy Spreadsheet Guide 2026: How to Use a Product Directory Without Skipping Verification`,shortTitle:`How to use a Lolobuy spreadsheet carefully`,description:`A practical guide to using a Lolobuy spreadsheet for discovery, checking source listings, reading QC information and avoiding rushed buying decisions.`,eyebrow:`SPREADSHEET BASICS`,published:`2026-07-26`,updated:`2026-07-26`,readingTime:`13 min read`,factCheckLine:`Fact-checked against LoloBuy's public website and current community ordering guide on July 26, 2026.`,visual:{eyebrow:`THE FOUR-SOURCE RULE`,title:`One decision, four different sources.`,caption:`The directory starts the search. The live listing, warehouse evidence and final parcel quote each take over at a different stage.`,items:[{label:`Directory`,text:`Find a product idea and compare categories.`},{label:`Live listing`,text:`Confirm the seller, option, current price and description.`},{label:`Warehouse QC`,text:`Inspect the physical item that arrived for your order.`},{label:`Packed parcel`,text:`Choose shipping from current weight, dimensions and eligibility.`}]},sources:[{label:`LoloBuy public website`,note:`Public purchasing, warehouse inspection, photography and 90-day storage statements.`},{label:`LoloBuy community ordering guide`,note:`Public nine-stage ordering overview posted in the platform's named Reddit community.`}],intro:[`A useful Lolobuy spreadsheet is not simply a long wall of product links. Its real job is to reduce the time between having a vague idea and reaching a listing that you can evaluate properly. Categories, clear search terms and readable product pages help with discovery; they do not remove the need to verify the seller page, current price, options and shipping restrictions.`,`This guide explains a cautious workflow for moving from an editorial find to a purchase decision. It deliberately separates what a directory can tell you from what must be confirmed on the destination page or later in warehouse quality-control photos.`],sections:[{heading:`Start with intent, not with an endless feed`,paragraphs:[`Before opening dozens of products, write down the category, preferred material, approximate measurements, acceptable color range and maximum item price. That small brief gives every later comparison a purpose. A shopper looking for a lightweight jacket for spring has a different decision to make from someone seeking a padded winter layer, even when both products sit under the same category.`,`Use broad category pages to learn the available vocabulary, then narrow your search. Search terms that describe the item itself usually work better than a long string of brand references: try the garment type, material, color or construction detail. If the search result is too broad, remove decorative words and keep the attributes that matter.`],bullets:[`Define the item type and its intended use.`,`Record must-have measurements or fit preferences.`,`Set separate limits for the item price and the total landed cost.`,`Keep two or three candidates instead of committing to the first result.`]},{heading:`Treat every directory entry as a lead`,paragraphs:[`Product directories can organize links, but listings are controlled by their destination websites. Sellers can change photos, stock, variants, prices, descriptions and shipping availability without the directory changing at exactly the same moment. For that reason, the live destination page is the authority for the current offer.`,`Open the listing and check that its title, gallery, variant selector and description still refer to the product you expected. A low headline price may belong to a small accessory or a deposit rather than the item shown in the first image. Select the intended color and size before judging the displayed price.`,`If the seller provides a size chart, compare the garment measurements with an item you already own. Labels such as M or XL are not universal. Shoulder width, chest width, total length, sleeve length, waist and inseam are more useful than the printed size name.`]},{heading:`Know which parts of the LoloBuy flow are publicly confirmed`,paragraphs:[`LoloBuy's public homepage says that it assists with purchases from Chinese online and offline channels and that a shopper can begin by pasting a product link. It also says that, after the merchant sends the item to the warehouse, the warehouse conducts a quality inspection, takes photographs and provides 90 days of free storage. Those are useful, specific claims because they describe the hand-off points a shopper should expect.`,`A public ordering guide in LoloBuy's named Reddit community expands that flow into account creation, product selection, order submission, payment, procurement, warehouse arrival, QC photos, consolidation, route selection and tracking. We use that guide as supporting context, not as a substitute for the live account. Payment methods, available carriers, coupons and route names can change more quickly than an educational article.`,`This distinction matters for search quality. A helpful Lolobuy spreadsheet should explain the process the platform actually describes while refusing to invent a permanent fee table, a guaranteed delivery time or a fixed number of free QC images. When a public source is silent, the honest answer is to check the current order screen or ask support before paying.`]},{heading:`Turn a source link into an order note`,paragraphs:[`A raw marketplace URL is not enough when a listing has many options. Alongside the link, record the exact color name, size, quantity and any seller instruction that affects the order. Save the relevant size chart and note whether the displayed price changed after selecting the option. This takes less than a minute and gives the warehouse stage a clean reference.`,`If a listing uses translated text, keep the original option wording as well as your translation. Two colors can receive nearly identical machine-translated names, and a seller may identify a variation by an image rather than a sentence. A precise note reduces ambiguity without pretending that the directory controls how the seller fulfils the order.`],bullets:[`Source URL and date checked`,`Exact option wording and reference image`,`Size chart or key measurements`,`Visible product price and domestic-delivery line`,`One sentence describing the non-negotiable detail`]},{heading:`Be skeptical of spreadsheet claims that outrun the evidence`,paragraphs:[`Words such as verified, best, cheapest and daily updated sound useful but need proof. A product being present in a directory does not prove that the seller is reliable, the item is authentic, the link was checked today or the final parcel will be inexpensive. A responsible directory dates meaningful reviews, links to the live destination and explains what it did and did not verify.`,`The same rule applies to customer reviews. A detailed post with order context and visible QC examples is more useful than an anonymous five-star sentence, but one successful order still does not establish a platform-wide rate. Read reviews for the specific evidence they contain—handling of a mismatch, image clarity, response timing or parcel outcome—and avoid turning a single report into a universal promise.`]},{heading:`Separate listing photos from warehouse QC photos`,paragraphs:[`Seller photos are marketing material. Warehouse quality-control photos document the physical item that arrived for your order. The two image sets answer different questions. The seller page helps you understand the promised design and options; QC photos help you compare the received item with that promise.`,`Lolobuy's public shopping flow describes inspection and photographs after an item reaches the warehouse. Exact photo coverage and any optional services can change, so confirm the current service details inside the platform before relying on a particular angle or number of images.`,`When QC images become available, first verify the basic identity of the item: color, selected variant, quantity and visible size tag. Then move to construction, symmetry and obvious damage. A request for an additional image should be specific—such as a close-up of a seam or a measurement beside a ruler—rather than a general request for a better photo.`]},{heading:`Calculate a decision price, not only an item price`,paragraphs:[`The amount on the product page is only one part of the final cost. Domestic delivery to the warehouse, service charges where applicable, international shipping, packaging choices and destination-country taxes can all affect the total. Bulky but inexpensive items can be costly to ship because some routes use volumetric weight.`,`A simple planning estimate is enough at the discovery stage: item price plus domestic delivery plus a conservative share of international shipping. Do not present that estimate as a quote. Final shipping options depend on the packed parcel, route, destination and current carrier rules.`],bullets:[`Check whether domestic shipping is included or added later.`,`Note estimated item weight and whether the item is unusually bulky.`,`Leave room for packaging and consolidation changes.`,`Review the final parcel quote before submitting international shipping.`]},{heading:`Keep a short verification record`,paragraphs:[`When comparing several products, save the destination URL, selected option, seller size chart, current price and the date you checked it. A screenshot can help when a listing changes, but the live page still controls the order. This record also makes it easier to explain a mismatch during the warehouse stage.`,`Bookmarks on this site are a lightweight browsing aid for the current page session. They are not a guarantee that a listing will stay available. Return to the destination page before ordering and repeat the essential checks.`]},{heading:`The practical rule`,paragraphs:[`Use a Lolobuy spreadsheet to discover and organize. Use the live listing to confirm what is being sold. Use warehouse QC photos to inspect what physically arrived. Use the final parcel quote to choose shipping. Keeping those four stages separate prevents a directory from being mistaken for a seller, an inspector or a freight quotation.`]}]},{slug:`how-to-read-qc-photos`,title:`How to Read Warehouse QC Photos: A Practical Checklist for Clothing, Shoes, Bags and Accessories`,shortTitle:`A practical warehouse QC photo checklist`,description:`Learn what warehouse QC photos can show, what they cannot prove, and how to review shape, measurements, construction, damage and order details.`,eyebrow:`QC FIELD GUIDE`,published:`2026-07-26`,updated:`2026-07-26`,readingTime:`13 min read`,factCheckLine:`Fact-checked July 26, 2026. LoloBuy publicly confirms warehouse inspection and photos; exact photo counts and paid extras are not stated on its public homepage.`,visual:{eyebrow:`QC TRIAGE`,title:`Review the evidence in the right order.`,caption:`A calm sequence prevents a tiny cosmetic detail from distracting you from the wrong size, missing piece or structural problem.`,items:[{label:`Identity`,text:`Item, color, size, quantity and included pieces.`},{label:`Structure`,text:`Shape, symmetry, alignment and visible damage.`},{label:`Measurements`,text:`Fit-critical dimensions compared with a known item.`},{label:`Action`,text:`Accept, request one focused check, or use the current remedy.`}]},sources:[{label:`LoloBuy public website`,note:`Confirms quality inspection and photography after warehouse arrival.`},{label:`Early independent LoloBuy user report`,note:`One shopper's preliminary report on QC photos, a size mismatch and support response; not a representative score.`}],intro:[`Warehouse QC photos are most useful when you approach them with a checklist. Looking only for an overall impression makes small but important problems easy to miss; zooming into every pixel can create false alarms caused by lighting, compression or the camera angle.`,`The goal is not to prove that an item is perfect. It is to confirm that the received item matches the order closely enough for you to make an informed accept, exchange or return decision within the platform's available process.`],sections:[{heading:`Begin with order identity`,paragraphs:[`Before examining stitching or texture, confirm that the photographs belong to the correct item. Compare the ordered color, model, size and quantity with what is visible. Look for the size tag or packaging label where it is shown, but remember that a tag alone does not prove fit.`,`Check whether the set is complete. Shoes should normally appear as a pair; a multi-piece outfit should include the expected pieces; accessories advertised with a strap, pouch or detachable part should be compared with the listing contents. Packaging may differ from marketing photos and should not be assumed unless it was explicitly part of the offer.`],bullets:[`Correct item type and color`,`Correct size or selected variant`,`Correct quantity and expected pieces`,`No obvious transit or handling damage`]},{heading:`Keep the public fact boundary clear`,paragraphs:[`LoloBuy's public homepage confirms that items are inspected and photographed after the merchant sends them to the warehouse. It does not, on the public page we checked, specify a universal number of free photographs, a permanent price for extra angles or a guaranteed video-inspection service. Those details should therefore be verified in the current account interface or with support, not copied from an old promotion or another agent's policy.`,`That boundary is practical, not merely cautious wording. QC coverage can differ by product type, service tier or current warehouse procedure. Build your first decision from the images that are actually attached to the order. If a critical question remains, check what focused inspection options are available before the return or exchange window closes.`]},{heading:`Read shape and symmetry before small details`,paragraphs:[`Large structural problems matter more than tiny cosmetic variation. For clothing, compare sleeve length, shoulder alignment, collar shape and the way the garment lies flat. For shoes, compare the left and right toe shape, heel height, panel placement and sole alignment. For a bag, inspect the overall silhouette, handle placement and whether the body sits evenly.`,`Camera perspective can exaggerate asymmetry. Use several angles when they are available and compare features that sit at the same distance from the camera. If only one angle makes a part look distorted, ask whether perspective or folding could explain it before treating it as a defect.`]},{heading:`Allow for lighting, compression and camera distance`,paragraphs:[`Warehouse photographs are evidence, but they are still photographs. Overhead lighting can make black fabric look washed out, a warm bulb can shift white toward cream, and a wide-angle phone lens can make the nearest edge appear larger. Image compression can also turn fine texture into blocky noise. Compare the same feature across several frames before deciding that the physical item is discolored or misshapen.`,`Use fixed references when they are visible. A neutral background, ruler, size tag, outsole edge or repeated panel can help you judge scale and alignment. If exact color is central to the purchase, ask for a clearly described lighting condition when the platform offers that option, while accepting that no screen reproduces color perfectly.`]},{heading:`Use measurements to answer fit questions`,paragraphs:[`A photograph cannot tell you how a garment will fit without a reference. Measurement images are therefore among the most valuable QC records. Compare the ruler placement with the seller's chart and with a garment you know fits. Make sure the item is laid flat and that the measurement starts at the correct seam or edge.`,`Allow for small differences caused by manual measurement, fabric stretch and how the garment is positioned. A meaningful discrepancy is one that changes the intended fit, not a few millimeters created by a tilted ruler. If a critical measurement is missing, request that exact measurement rather than a generic extra photo.`]},{heading:`Ask for one answer, not simply more photos`,paragraphs:[`A vague request such as “take a better picture” leaves the photographer to guess what matters. A useful request names the feature, angle and reference: measure the insole from heel to toe; photograph the left shoe's inner panel beside the right shoe; show the jacket chest width with the garment flat; or capture the zipper teeth at the point where they appear misaligned.`,`Prioritize requests that can change the decision. An extra logo close-up may be interesting, but a missing size measurement, cracked component or incorrect color is more likely to determine whether you accept the order. Group related questions when the service permits it, and avoid asking for a photograph that still cannot establish comfort, material composition or long-term durability.`],bullets:[`Name the exact feature or measurement.`,`State the angle or comparison you need.`,`Explain the suspected mismatch in one sentence.`,`Choose evidence that could change the accept-or-action decision.`]},{heading:`Clothing checklist`,paragraphs:[`For tops and jackets, inspect the neckline, zipper path, button spacing, print or embroidery placement, pocket symmetry and major seam lines. Check for stains, pulls, holes and visibly loose stitching. Dark garments may hide details in underexposed images, while pale fabrics can look warmer or cooler under warehouse lighting.`,`For trousers and shorts, compare the rise, leg shape, waistband, pocket placement and hem. If the style depends on a wash or pattern, compare the overall treatment rather than expecting every mark to be identical to a sample photograph.`]},{heading:`Shoes, bags and accessory checklist`,paragraphs:[`For shoes, compare both sides of the pair, outsole attachment, visible glue, stitching paths, lace hardware, heel counters and the alignment of repeated panels. Minor adhesive traces can look dramatic in a close crop; decide whether they are removable cosmetic residue or a sign of separation.`,`For bags, inspect the front and back shape, corners, handles, strap attachments, zipper path, lining and hardware color. Request a close-up when a clasp, engraving or seam is important. For jewelry and small accessories, scale is easy to misread, so use item dimensions and a ruler image when available.`]},{heading:`Know what photos cannot establish`,paragraphs:[`QC photos cannot reliably prove long-term durability, exact material composition, comfort, electronics performance or authenticity. They also cannot show every hidden seam or internal component. Treat claims that every photographed item is fully verified with caution unless the service clearly defines what was inspected.`,`Color accuracy is limited by lighting and screens. If a precise shade matters, compare multiple images and the seller's option name, but expect some uncertainty. Odor, softness and sound are also outside the normal scope of a photograph.`]},{heading:`Save the evidence before the parcel moves on`,paragraphs:[`Keep the order reference, listing screenshot, selected option and important QC frames together until the transaction is complete. If you raise an issue, record the date, the image number and the outcome you requested. A short evidence trail is easier for support to follow than a long message built from memory.`,`Do not let documentation become a reason to miss a deadline. Warehouse remedies depend on the seller and the platform's current process, and some listings may limit returns. Check the available action and time window first, then provide the clearest evidence you have. A good QC review ends with a timely decision, not an endlessly growing gallery.`]},{heading:`Make a calm accept-or-action decision`,paragraphs:[`Classify findings into three groups: normal variation, a cosmetic issue you can accept, and a mismatch or defect that materially affects the order. Then check the platform's current deadline and available action. If you contact support, identify the photo, location and requested outcome clearly.`,`Lolobuy publicly describes warehouse inspection and photography in its shopping flow, but service details and remedies may change. The current order page and support process are the authority for deadlines, extra-photo requests, exchanges and returns.`]}]},{slug:`plan-china-shopping-haul`,title:`Planning a China Shopping Haul: Storage, Consolidation, Weight and Shipping Decisions`,shortTitle:`Plan storage, consolidation and shipping`,description:`A grounded haul-planning guide covering warehouse storage, consolidation, actual and volumetric weight, packaging choices and route checks.`,eyebrow:`SHIPPING PLANNER`,published:`2026-07-26`,updated:`2026-07-26`,readingTime:`13 min read`,factCheckLine:`Fact-checked July 26, 2026. The 90-day storage statement is public; live route prices and eligibility must be checked on the packed parcel.`,visual:{eyebrow:`LANDED-COST STACK`,title:`The product price is only the first line.`,caption:`Keep estimates and confirmed charges separate. The final international choice becomes meaningful only after the warehouse has parcel data.`,items:[{label:`Product`,text:`Selected variant at the current seller price.`},{label:`China-side cost`,text:`Domestic delivery and any clearly disclosed order charges.`},{label:`Parcel`,text:`Packaging, actual weight, dimensions and route rules.`},{label:`Destination`,text:`International freight plus applicable tax or customs obligations.`}]},sources:[{label:`LoloBuy public website`,note:`Public 90-day free-storage and warehouse-service statements.`},{label:`LoloBuy community ordering guide`,note:`Describes consolidation, route selection, international payment and tracking stages.`}],intro:[`A haul is not cheaper merely because several items travel together. Consolidation can reduce repeated base charges and unused packaging, but parcel size, route restrictions and timing still matter. Good planning begins before the first item reaches the warehouse.`,`Lolobuy's public website currently advertises 90 days of free storage and describes consolidation followed by international shipping. Treat that as a planning window rather than a reason to wait until the last day; always confirm the live storage terms and order deadlines in your account.`],sections:[{heading:`Start with what LoloBuy actually publishes`,paragraphs:[`LoloBuy's public website says that it assists with purchases from Chinese sales channels, inspects and photographs goods after warehouse arrival, and provides 90 days of free storage. A public ordering guide in its named Reddit community describes storing multiple arrivals, consolidating them, selecting an international route and receiving tracking after dispatch. Together, those sources support the basic warehouse-agent flow.`,`They do not create a permanent price list for your parcel. The public homepage does not give one universal shipping rate, because a usable quote needs a destination, an eligible line and parcel data. Route names, delivery estimates, restricted-item rules, compensation and promotions can change. A responsible shipping guide therefore teaches the questions to ask instead of copying a price that may already be stale.`,`The same caution applies to the 90-day statement. It is a public planning fact as of the date of this guide, not permission to ignore the order clock. Check how the account displays each item's storage start and any exceptional status, then set your own deadline comfortably earlier.`]},{heading:`Build the parcel on paper first`,paragraphs:[`List each intended item with an estimated weight, broad dimensions, material and any special handling concern. You do not need perfect data at the browsing stage. The purpose is to notice combinations that may create a poor parcel, such as a bulky puffer jacket mixed with dense footwear or a fragile accessory surrounded by heavy items.`,`Separate wants from must-haves. If one late item would hold the entire parcel beyond your preferred shipping date, decide in advance whether you would ship without it. That avoids a rushed choice after other items have already arrived.`]},{heading:`Keep estimates in ranges`,paragraphs:[`A pre-purchase weight from a seller page is useful for rough planning, but it is not the packed weight. Size selection, retail boxes, protective material and consolidation all change the result. Record a low and high estimate instead of one precise-looking number. The range reminds you that the cost is unresolved while still helping you spot a parcel that is likely to be dense or bulky.`,`Do the same with timing. Seller dispatch, Chinese domestic delivery, warehouse intake, QC review, problem resolution, packing, export handling and destination customs are separate stages. Adding their advertised best-case times produces false confidence. Build a buffer around the date you actually need the parcel and avoid ordering time-sensitive goods with no room for delay.`],bullets:[`Estimated item weight: low and high`,`Likely retail packaging: removable or protective`,`Fit with other items: compatible, fragile or restricted`,`Personal ship-by date: earlier than the storage maximum`]},{heading:`Understand actual and volumetric weight`,paragraphs:[`Actual weight is what the packed parcel weighs on a scale. Volumetric weight converts the parcel's outer dimensions into a chargeable weight using the carrier's formula. A carrier may charge whichever is higher. The divisor and rules vary by route, so a generic online calculator is only an estimate.`,`Soft items may compress; rigid shoe boxes, helmets and decorative objects may not. Removing unnecessary retail packaging can reduce volume, but it can also reduce protection or affect the condition in which an item arrives. Decide based on the item, not a blanket rule.`],bullets:[`Dense and compact items are usually driven by actual weight.`,`Light but bulky items can be driven by volumetric weight.`,`Outer packaging and protective materials change both figures.`,`The warehouse parcel data is more useful than a pre-purchase guess.`]},{heading:`Use warehouse storage as a buffer`,paragraphs:[`Storage allows items from different sellers and arrival dates to wait for consolidation. It also gives you time to review QC photos and resolve a problem before international shipping. Record the warehouse arrival date of each item and set an earlier personal deadline than the platform maximum.`,`Do not assume every item shares the same storage clock or status. Cancelled, returned or exceptional orders may follow different rules. Lolobuy's public 90-day statement is helpful context, but the order record and current terms should guide action.`]},{heading:`Consolidate with compatibility in mind`,paragraphs:[`A good consolidated parcel combines items that can travel safely and through the same route. Batteries, liquids, magnets, food, branded goods and other restricted categories can face route limitations. Restrictions vary by destination and carrier and can change, so check eligibility before building the entire plan around one shipping line.`,`Heavy items can crush softer goods if internal packing is poor. Fragile products may benefit from reinforcement, corner protection or a separate parcel. Packaging services can add weight and dimensions, but that trade-off can be worthwhile when damage risk is meaningful.`]},{heading:`Compare consolidation with splitting honestly`,paragraphs:[`Consolidation can remove duplicated outer boxes and may avoid paying several minimum or first-weight charges. That does not mean one large parcel is always cheaper. A bigger carton can cross a route's size threshold, trigger volumetric weight, mix an ineligible item with otherwise eligible goods or concentrate too much value and risk in one shipment.`,`Splitting can isolate a restricted or fragile product and keep the rest of the haul on a suitable line. It can also duplicate base charges, packaging and tracking work. Compare the two realistic parcel plans after warehouse weights and dimensions are available: one consolidated quote versus two eligible quotes. Do not compare one confirmed price with a guessed alternative.`,`There is also a practical middle ground. Remove unnecessary packaging from soft goods where safe, keep protection for structured or fragile items, and group products by compatible route. The goal is not the fewest boxes; it is the best balance of eligibility, protection, cost and the consequences if one parcel is delayed.`]},{heading:`Compare routes on more than headline price`,paragraphs:[`The cheapest route is not automatically the best fit. Compare chargeable weight rules, estimated delivery window, tracking quality, compensation limits, restricted-item policy and destination-country handling. Estimated delivery is not a guarantee, especially around holidays, weather disruptions and customs processing.`,`Taxes and import rules belong to the destination country. A shopping directory cannot determine your legal obligations. Review the carrier description and official customs guidance for your destination, and declare contents accurately.`]},{heading:`Read tracking as a sequence of scans`,paragraphs:[`Tracking usually records events, not continuous movement. A parcel can travel between facilities while the public page shows no new scan. The first tracking number may belong to a logistics partner before a local carrier receives the shipment, and translated status text can be vague. Keep the parcel number, route name and dispatch date together so you know which party currently has the useful information.`,`A quiet tracking period is not by itself proof that the parcel is lost. Compare it with the route's current guidance and contact the appropriate support channel when it exceeds that guidance or shows an exception. Customs review and local delivery sit outside the warehouse's direct control, so avoid promising readers a fixed arrival date.`]},{heading:`Rehearse the final submission`,paragraphs:[`Before paying for international shipping, review the parcel contents, delivery address, selected route, declared information, insurance or protection options, packaging requests and final chargeable weight. Keep the parcel number and tracking information together.`,`If the final quote is much higher than the planning estimate, look for the cause rather than immediately switching routes. Parcel dimensions, added packaging, a restricted category or a different weight rule may explain the gap. A smaller parcel split can sometimes help, but it can also repeat base charges.`]},{heading:`A useful planning rhythm`,paragraphs:[`Browse with total cost in mind, inspect each arrival, resolve issues early, consolidate compatible items, compare eligible routes and review the final parcel before payment. That rhythm uses the warehouse as a decision point rather than treating it as an automatic conveyor belt.`]}]},{slug:`lolobuy-review-early-user-experience`,title:`Lolobuy Review 2026: What an Early User Report Tells Us—and What It Does Not`,shortTitle:`Lolobuy review: useful evidence, clear limits`,description:`A source-led Lolobuy review examining one detailed early shopper report, the QC mismatch it documented, and the important questions that still require a completed parcel.`,eyebrow:`REVIEW EVIDENCE`,published:`2026-07-26`,updated:`2026-07-26`,readingTime:`14 min read`,factCheckLine:`Research checked July 26, 2026. This article separates LoloBuy's own claims from one independent shopper's preliminary experience.`,visual:{eyebrow:`EVIDENCE LADDER`,title:`A useful review shows where every claim comes from.`,caption:`Platform statements explain the intended service. A shopper report documents one experience. Your own order screen controls current prices, options and deadlines.`,items:[{label:`Published service`,text:`Link purchasing, warehouse inspection, photos and 90-day storage.`},{label:`Observed case`,text:`One shopper reported a caught size mismatch and a handled return.`},{label:`Still unknown`,text:`Completed shipping cost, parcel outcome and repeat-order consistency.`},{label:`Your verification`,text:`Check the live quote, evidence and current remedy before paying.`}]},sources:[{label:`LoloBuy public website`,note:`Primary source for public purchasing, inspection, photography and storage claims.`},{label:`Preliminary independent shopper report`,note:`First-person report covering footwear, handbags, QC, support and a size-mismatch case.`},{label:`LoloBuy community ordering guide`,note:`Public process description used to compare the reported experience with the advertised workflow.`}],intro:[`Most young shopping services accumulate promotional videos long before they accumulate enough independent, completed-order evidence for a confident verdict. LoloBuy is in that stage. Its public website explains a recognizable warehouse-agent model, and recent community posts show people testing the service, but the searchable review base is still small. Calling it universally excellent—or universally unsafe—would outrun the evidence.`,`This review takes a narrower approach. It examines a detailed preliminary report from a Reddit user who said they had purchased footwear and handbags through LoloBuy, compares the observations with LoloBuy's published process, and lists the parts of a complete shopping cycle that the post had not yet tested. The result is more useful than a star rating because readers can see exactly what supports each conclusion.`],sections:[{heading:`Why the word preliminary matters`,paragraphs:[`The author explicitly presented the post as early thoughts, not a final haul review. At that point, they discussed purchasing, warehouse QC, the handling of a mismatch, the interface and customer service. They also said a full review would come after the haul. That means the report contains meaningful evidence about the China-side stages, but it should not be used as proof of international shipping speed, final freight cost, customs handling or the parcel's delivered condition.`,`This is not a weakness in the post. Clear scope is one sign of a credible review. The problem begins when another website removes that qualifier and turns an unfinished case into a blanket claim such as “fast worldwide delivery.” We keep the original boundary visible.`]},{heading:`What the shopper actually tested`,paragraphs:[`The reviewer said they had used LoloBuy for both shoes and handbags. That gives the report more substance than an account-registration walkthrough because physical orders reached a stage where photographs and order handling could be assessed. The author also linked to separate QC posts, giving readers a way to inspect some of the visual context rather than relying only on praise.`,`The range is still narrow. Two product categories and one user's early orders cannot tell us how the warehouse handles electronics, fragile home goods, batteries, unusual custom requests or a large mixed parcel. Nor does it establish average processing time. The evidence is specific: this shopper's footwear and handbag purchasing stages were described positively.`]},{heading:`The two-different-sizes incident is the most useful detail`,paragraphs:[`The strongest part of the report is not the general statement that the experience felt smooth. It is the description of a concrete mismatch: the order contained two shoes in different sizes. According to the shopper, LoloBuy noticed the problem and handled a return even though the source listing was described as B-grade, a category where remedies can be more restricted.`,`That incident aligns with the practical purpose of warehouse inspection. LoloBuy's public homepage says it conducts quality inspection and takes photos after goods arrive. Catching an obvious size mismatch before international dispatch is exactly the kind of avoidable loss that the warehouse stage should prevent.`,`One successful intervention does not establish a guaranteed return policy. Seller rules, listing conditions, timing and the nature of a defect can change the available remedy. The useful conclusion is narrower: in this documented case, the inspection process surfaced a material mismatch and support helped the shopper address it before shipping.`]},{heading:`What “solid QC photos” can and cannot tell us`,paragraphs:[`The reviewer described the QC images positively. That is encouraging, particularly because linked QC posts allow readers to judge framing and detail for themselves. It also fits the platform's published statement that warehouse arrivals are photographed.`,`Image quality is only one layer of QC. A clear photograph can help confirm the pair, size label, color, overall shape and visible defects. It cannot prove comfort, material composition, durability, authenticity or every hidden construction detail. A fair review should not convert good-looking photos into a guarantee about the product.`,`There is another missing public detail: the LoloBuy homepage we checked does not publish a universal free-photo count, a fixed extra-photo price or a permanent video-inspection fee. Anyone comparing agents should verify those current terms in the account rather than borrow numbers from an old social post.`]},{heading:`The interface and browsing-history comments are useful, but personal`,paragraphs:[`The shopper found the interface intuitive and noted that prior searches remained available, reducing the need to keep every product link separately. That feature could be genuinely helpful when comparing several marketplace listings. It does not replace a personal order record, because a seller can edit or remove a listing and search history may not preserve the exact option you intended.`,`Ease of use is also subjective. A frequent warehouse-agent user may understand status labels that confuse a first-time buyer. When evaluating the interface yourself, check whether the cost lines are understandable, selected options remain visible, QC images are easy to match to the order, and the parcel screen clearly separates estimates from final charges.`]},{heading:`Responsive support in one case is a positive signal, not a service-level promise`,paragraphs:[`The reviewer described customer service as responsive during the early experience. Combined with the handled size mismatch, that gives the praise a concrete context. It suggests that support was reachable and able to move one order toward a remedy.`,`Response quality should be judged over more than a single uncomplicated exchange. Time zones, sales events, warehouse volume and the complexity of a seller dispute can change the experience. A stronger long-term review would record when the issue was submitted, when a useful response arrived, whether the resolution matched the request and whether any cost was clearly explained.`,`For your own order, write short support messages that identify the item, photograph and requested outcome. Clear evidence makes the interaction easier to evaluate and reduces back-and-forth regardless of the platform.`]},{heading:`The referral link should remain visible in the evidence assessment`,paragraphs:[`The Reddit post included a LoloBuy invitation link. Referral links can create an incentive, so readers should know one was present. That does not automatically make the described size mismatch, linked QC posts or support interaction false. It simply means the review should be weighed by the specificity and verifiability of its evidence rather than accepted because the tone is positive.`,`Good review writing handles this openly. It distinguishes observed events from opinion, notes any referral relationship and avoids claims the author did not test. A promotional link hidden behind a supposedly neutral verdict is much less useful than a disclosed link beside a well-documented order.`]},{heading:`The biggest unanswered questions begin at parcel submission`,paragraphs:[`The preliminary post did not yet provide a completed international-shipping comparison. It did not publish the final packed weight and dimensions, route chosen, freight paid, transit time, customs outcome, delivery condition or any compensation claim. Those are not minor details; for many shoppers, international freight is the largest uncertain cost.`,`It also cannot tell us how consistent the service is across repeat orders. A robust follow-up would compare several purchase times, QC turnaround, packing accuracy and support outcomes. It would show the original seller cost separately from China-side delivery and international freight, then explain any coupon or balance adjustment without presenting a temporary promotion as a standard price.`,`Until that evidence exists, readers should treat claims such as cheapest, fastest or best agent as unproven. Use LoloBuy's live estimator or parcel screen for a current route decision and compare like with like: the same destination, chargeable weight, category and protection level.`]},{heading:`How to run a low-assumption first order`,paragraphs:[`If the public workflow and early report make LoloBuy worth considering, test the service with an order whose size, color and condition can be judged clearly. Keep the source listing, selected option and seller terms. When the item arrives, review identity and measurements before cosmetic details, and check the current deadline for any action.`,`Do not build a large time-sensitive haul around an untested estimate. Use the warehouse stage to learn how the account presents QC, storage and parcel options. Before international payment, compare the final packed data, eligible routes, tracking description, compensation terms and destination obligations.`],bullets:[`Choose an item with clear options and a usable size chart.`,`Save the exact listing and selected variant.`,`Evaluate the QC evidence before adding more orders.`,`Wait for packed parcel data before judging freight.`,`Record the delivered result so the review covers the complete cycle.`]},{heading:`A careful verdict`,paragraphs:[`The available early report is a positive signal for the purchasing and warehouse stages. It describes a real mismatch being caught, a return being handled, usable QC photographs, an approachable interface and responsive support. Those details are more persuasive than generic praise because they describe what happened.`,`They are not enough for a platform-wide score. The searchable independent sample remains small, the report was explicitly preliminary, and the international parcel had not yet supplied the evidence needed to judge total cost or delivery. The honest 2026 conclusion is that LoloBuy shows promising early warehouse-stage evidence, while shoppers should still verify current terms and judge the service through a complete, documented order.`]}]}],f=[{question:`What is a Lolobuy spreadsheet?`,basis:`INDEPENDENT DIRECTORY`,answer:`A Lolobuy spreadsheet is an independent product-discovery directory that groups product links, categories and practical buying guidance in one place. It is not a service described or operated by LoloBuy on its public homepage, and it is not a substitute for the live product listing. Use the directory to discover an item, then recheck the current title, seller, selected colour or size, quantity, price and China-side delivery charge on the destination page before submitting an order. A spreadsheet link is a lead, not evidence that an item is still in stock, that the seller is reliable or that the physical product has passed warehouse inspection.`},{question:`Is Lolobuy Sheet an official Lolobuy website?`,basis:`INDEPENDENT DIRECTORY`,answer:`No. Lolobuy Sheet is an independent product-discovery and educational website. It is not owned, operated or endorsed by LoloBuy. The service facts in this FAQ were checked against LoloBuy's publicly indexed English homepage on July 26, 2026, but live account information still controls an actual order. Product availability, service options, warehouse deadlines and charges can change after a page is researched. A product card on this site is not an offer from LoloBuy and does not create a promise about price, stock, inspection results, shipping eligibility or delivery.`},{question:`Does this site sell, store or ship products?`,basis:`INDEPENDENT DIRECTORY`,answer:`No. This site organizes product finds and explains the buying process; it does not accept payment, purchase from sellers, inspect goods, operate a warehouse or arrange international delivery. Each product card first opens an independent detail page so that you can review the item reference and a pre-order checklist. Only the final product button continues to the current ordering destination. Any order status, payment, warehouse photograph, return request, parcel quote or tracking update belongs to the service handling that transaction, not to this directory.`},{question:`What does LoloBuy officially say its buying service does?`,basis:`CONFIRMED ON OFFICIAL HOMEPAGE`,answer:`LoloBuy's public English homepage says it assists users with purchasing products from channels in China, both online and offline. It also says a user can paste a product link to begin the order. That wording supports describing LoloBuy as a purchasing service rather than the original seller of every listed item. The homepage does not turn every Chinese listing into a guaranteed order: seller availability, product restrictions, incomplete information or a changed listing can still require confirmation. For a real purchase, preserve the original link and verify the exact variant and displayed cost in the order record before payment.`},{question:`How does a LoloBuy order begin with a product link?`,basis:`CONFIRMED ON OFFICIAL HOMEPAGE`,answer:`The official homepage says that you only need to paste a product link to complete the order process. In practice, the link identifies the seller page, but it may not communicate your intended size, colour, version or quantity. Before submitting it, open the live listing and record the exact option you want, the seller price and any visible China-side delivery charge. After pasting the link, compare the generated order information with the source listing instead of assuming the first image or lowest displayed price represents your choice. If the listing cannot be read correctly, do not guess; wait for the order details to be clarified.`},{question:`Which product links can be submitted to LoloBuy?`,basis:`OFFICIAL CLAIM, WITH A CLEAR LIMIT`,answer:`The public homepage uses broad language: it says LoloBuy assists with purchases from online and offline channels in China and lets users start by pasting a product link. The homepage we checked does not publish a complete marketplace whitelist, a guaranteed list of supported sellers or a promise that every product category can be purchased and shipped. Therefore, this FAQ does not copy a marketplace list from a community post or another agent. Paste the current seller link, check whether the order page can identify it correctly, and confirm any product or route restriction before paying.`},{question:`Are all product links on this directory manually verified every day?`,basis:`INDEPENDENT DIRECTORY POLICY`,answer:`No daily-verification claim is made. Seller listings can be edited, removed, repriced or placed out of stock without notice, and a directory cannot guarantee the continuing accuracy of every external page. Treat each product card as a discovery reference, open its detail page, and verify the current destination listing immediately before ordering. Pay particular attention to the selected variant because the lowest price may belong to a different size, colour, accessory or deposit. If the product title, image or options no longer match the directory entry, rely on the live listing and do not place the order from an old assumption.`},{question:`What happens after the seller sends an item to the LoloBuy warehouse?`,basis:`CONFIRMED ON OFFICIAL HOMEPAGE`,answer:`LoloBuy's official homepage says that after the merchant sends the goods to its warehouse, the service conducts a quality inspection, takes photographs for the user and provides 90 days of free storage. Those are the clearest publicly indexed warehouse facts available on the site. The same homepage does not publish the complete inspection checklist, the photo count, the processing time or the remedy for every defect. When the warehouse record appears, compare it with the saved order details and raise any visible mismatch before arranging international shipment; sending the parcel removes the opportunity to inspect it at the warehouse stage.`},{question:`What does QC mean on a LoloBuy order?`,basis:`OFFICIAL WAREHOUSE PROCESS EXPLAINED`,answer:`QC means quality control. LoloBuy's homepage specifically states that warehouse arrivals receive a quality inspection and photographs. Those images help a buyer compare the physical arrival with the ordered item before international shipping. Start with objective checks: product type, colour, labelled size, quantity and obvious damage. Then review symmetry, print or embroidery placement, stitching, measurements and other category-specific details that are actually visible. QC photographs are evidence of visible condition at a particular angle and time; they do not prove hidden construction, long-term durability, exact material composition, comfort, electronics performance or authenticity.`},{question:`How many free QC photos does LoloBuy provide?`,basis:`NOT PUBLISHED ON OFFICIAL HOMEPAGE`,answer:`The official homepage confirms that photographs are taken after warehouse arrival, but it does not publish a universal number of free QC images. This FAQ therefore does not borrow a photo count from another purchasing agent, a referral post or an old promotion. Check the actual image set attached to the warehouse order and judge whether it shows the details needed for your decision. If an important area is missing, identify the precise evidence required—for example, an insole measurement, a label, a damaged corner or the opposite side—then check whether the current account offers a suitable inspection request before any return deadline.`},{question:`Does LoloBuy offer extra photos or a warehouse video?`,basis:`NOT PUBLISHED ON OFFICIAL HOMEPAGE`,answer:`The publicly indexed homepage reviewed for this FAQ does not state a permanent extra-photo service, warehouse-video option, included quantity or price. It would be misleading to publish another platform's fee as if it were LoloBuy's. Before ordering an item that needs a specific measurement or functional view, check the current service options in the account or ask support whether that evidence can be produced. Make a focused request rather than asking for “more photos”: name the exact angle, label, measurement or visible feature needed, and confirm the charge and timing before relying on the request.`},{question:`How long is free LoloBuy warehouse storage?`,basis:`CONFIRMED ON OFFICIAL HOMEPAGE`,answer:`LoloBuy's official homepage currently advertises 90 days of free storage after goods reach the warehouse stage. The public page does not explain in the indexed text exactly when the 90-day clock begins, how exceptional items are handled or what fee or disposal rule applies after the free period. Record the warehouse-arrival date shown for every item and plan consolidation or shipment well before the final day instead of treating day 90 as a safe target. If items arrive on different dates, track each one separately because the oldest warehouse item can determine how much decision time remains.`},{question:`Can several LoloBuy orders be combined into one international parcel?`,basis:`NOT PUBLISHED ON OFFICIAL HOMEPAGE`,answer:`LoloBuy's public homepage confirms warehouse storage, but the indexed homepage text we checked does not publish a detailed consolidation policy or guarantee that every item can share one parcel. Do not present consolidation as automatic. Before building a multi-seller haul, confirm in the current parcel workflow whether the stored items can be selected together and whether any product restriction, size, protection requirement or route rule makes a split necessary. Compare the packed result rather than assuming that one large parcel is always cheaper; dimensions and route eligibility can matter as much as the item count.`},{question:`How much does LoloBuy international shipping cost?`,basis:`NO FIXED PRICE PUBLISHED`,answer:`The official homepage does not publish one fixed international-shipping price that can answer every order. A useful quote must be tied to the actual destination, packed weight and dimensions, eligible route, product restrictions and current charges shown for that parcel. Any article promising a universal per-kilogram total before the goods are packed is leaving out important variables. Use early estimates only for budgeting, then make the shipping decision from the current parcel data and payable amount. Also check what the quoted price includes and whether destination taxes, customs charges or remote-area fees remain separate.`},{question:`Does LoloBuy publish guaranteed delivery times, carriers or tracking rules?`,basis:`NOT PUBLISHED ON OFFICIAL HOMEPAGE`,answer:`The publicly indexed homepage used for this FAQ does not provide a complete, permanent table of international carriers, country coverage, delivery promises or tracking milestones. Route names and estimates can change, so a static FAQ should not turn them into guarantees. When a real parcel is ready, compare only the routes currently offered for the destination and product type. Record whether the time shown is an estimate or a guarantee, what compensation terms apply, when tracking is expected to update and which events are outside the carrier's control. Judge delivery performance from dispatch to receipt, not from the day the seller was paid.`},{question:`Does LoloBuy publish a fixed service fee or exchange-rate markup?`,basis:`NOT PUBLISHED ON OFFICIAL HOMEPAGE`,answer:`The public homepage text reviewed on July 26, 2026 does not state a universal service-fee percentage or fixed exchange-rate markup. This page therefore does not invent one. To understand the real purchase cost, compare the seller's current item price with the amount shown in the order breakdown, then separate China-side delivery, optional services, payment charges and later international freight. If the account converts currencies, compare the displayed rate and final payable amount at the same moment because market rates and payment-provider charges can move. A coupon should be shown as a separate reduction, not used to hide the underlying cost.`},{question:`Why can a product price change after I open a spreadsheet link?`,basis:`PRACTICAL LISTING CHECK`,answer:`A spreadsheet records a discovery reference, while the seller controls the live listing. The displayed headline price may belong to the cheapest variant, an accessory, a deposit or an option different from the first image; the seller may also change the price or remove stock after the directory was updated. LoloBuy's homepage explains that an order can begin from a pasted product link, but it does not promise that an old directory price will be honoured. Select the intended variant on the live page and compare the title, option, quantity, seller price and China-side delivery shown in the generated order before paying.`},{question:`What are LoloBuy's return or exchange rules after QC?`,basis:`NOT PUBLISHED ON OFFICIAL HOMEPAGE`,answer:`The official homepage confirms warehouse inspection and photographs, but the indexed page does not publish a complete return-and-exchange policy, seller deadline or fee table. The result can depend on the seller's own terms, the reason for the request and the current order status. Review warehouse images promptly, preserve screenshots of the ordered option and identify the mismatch with specific evidence. Then check the return or exchange action available for that order before authorising international shipment. Do not assume that a visible problem automatically creates a free return, and do not use another platform's deadline as if it were LoloBuy's rule.`},{question:`Are LoloBuy coupons and shipping discounts permanent?`,basis:`NO PERMANENT OFFER PUBLISHED`,answer:`The public homepage reviewed for this FAQ does not publish a permanent universal coupon value, minimum spend or guaranteed shipping discount. Promotions can be limited by account, route, destination, order value, code, start date or expiry date. Treat a coupon as valid only when the current checkout accepts it and shows the reduced payable amount. Compare the total after the discount, not the headline value alone, and avoid describing a temporary referral or event offer as a normal platform price. This FAQ intentionally omits coupon codes and dollar amounts that cannot be verified as current official terms.`},{question:`What does W2C mean on a Lolobuy spreadsheet?`,basis:`INDEPENDENT DIRECTORY TERM`,answer:`W2C commonly means “where to cop”: the source or destination link used to find a product. It is a shopping-community term, not a policy defined on LoloBuy's public homepage. A W2C link can help you locate a listing to paste into an ordering service, but it does not prove that the listing is current, that the photographed item is the variant you want or that the seller and product are acceptable for international shipping. Open the source, verify the exact option and current price, and keep the link with the order so the later warehouse photos can be compared with what was originally selected.`},{question:`What should I check in LoloBuy warehouse QC photos?`,basis:`PRACTICAL QC CHECKLIST`,answer:`The official homepage confirms inspection and photographs after warehouse arrival but does not publish a universal inspection checklist. Use a repeatable order: first confirm product type, colour, labelled size and quantity; next look for obvious damage, stains, missing parts or a wrong variant; then inspect category-specific details such as shape, symmetry, stitching, print placement, zips or measurements. Compare against the saved seller listing rather than memory. If lighting or angle prevents a fair conclusion, do not label the item defective from one ambiguous image. Check whether a precise additional inspection request is available before the relevant decision window closes.`},{question:`Can a Lolobuy spreadsheet or QC photo guarantee authenticity or import legality?`,basis:`IMPORTANT LIMIT`,answer:`No. LoloBuy's public homepage states that warehouse goods are inspected and photographed, but it does not publish a guarantee that those photographs authenticate branded goods or establish legal importability in every country. A directory link also cannot prove intellectual-property status, material composition, safety certification or compliance with destination customs rules. QC images are useful for visible comparison only. Before ordering, follow the platform's current restrictions and the laws that apply to the destination; for regulated, branded, battery-powered, liquid or otherwise sensitive products, confirm route eligibility and customs obligations rather than relying on a spreadsheet label.`}],p={es:[{name:`Gafas de esquí`,category:`Gafas`,description:`Entrada visual para unas gafas de esquí. Confirma lente, montura, piezas incluidas y disponibilidad en la ficha actual antes de pedir.`},{name:`Sombrero Gucci`,category:`Sombreros`,description:`Entrada visual para un sombrero con etiqueta Gucci. Confirma opción, medidas, construcción y datos actuales sin depender solo de la imagen.`},{name:`Sudaderas con capucha Off-White`,category:`Sudaderas`,description:`Entrada visual para sudaderas con etiqueta Off-White. Revisa diseño, medidas, posición del estampado y variante actual.`},{name:`Zapatillas de caña alta Numeris`,category:`Calzado`,description:`Entrada visual para zapatillas altas Numeris. Confirma talla y color y usa medidas y fotos QC para revisar el par recibido.`},{name:`HOKA Speedgoat 5`,category:`Calzado`,description:`Entrada visual para calzado con etiqueta HOKA Speedgoat 5. Confirma opción, talla y detalles actuales y compara ambos zapatos durante el QC.`},{name:`Mochila Nike Elite`,category:`Bolsos`,description:`Entrada visual para una mochila con etiqueta Nike Elite. Confirma dimensiones, compartimentos, correas, cierres y color actual.`},{name:`Chaqueta acolchada Balenciaga`,category:`Abrigos`,description:`Entrada visual para una chaqueta acolchada con etiqueta Balenciaga. Compara medidas, cierres, paneles y distribución del relleno.`},{name:`Chaqueta de invierno con capucha`,category:`Abrigos`,description:`Entrada visual para una chaqueta de invierno con capucha. Revisa talla, color, medidas, capucha, cierres, bolsillos y construcción visible.`}],de:[{name:`Skibrille`,category:`Brillen`,description:`Visueller Verzeichniseintrag für eine Skibrille. Linse, Rahmen, Lieferumfang und Verfügbarkeit im aktuellen Angebot prüfen.`},{name:`Gucci-Kappe`,category:`Kopfbedeckung`,description:`Visueller Eintrag für eine Gucci-gekennzeichnete Kappe. Option, Maße, Verarbeitung und aktuelle Angebotsdaten prüfen.`},{name:`Off-White-Hoodies`,category:`Hoodies`,description:`Visueller Eintrag für Off-White-gekennzeichnete Hoodies. Design, Maße, Druckposition und aktuelle Variante prüfen.`},{name:`Numeris High-Top-Schuhe`,category:`Schuhe`,description:`Visueller Eintrag für Numeris-High-Top-Schuhe. Größe und Farbe bestätigen und das eingegangene Paar anhand von Maßen und QC-Fotos prüfen.`},{name:`HOKA Speedgoat 5`,category:`Schuhe`,description:`Visueller Eintrag für einen HOKA-Speedgoat-5-gekennzeichneten Schuh. Option, Größe und Angebot prüfen und beide Schuhe beim QC vergleichen.`},{name:`Nike Elite-Rucksack`,category:`Taschen`,description:`Visueller Eintrag für einen Nike-Elite-gekennzeichneten Rucksack. Maße, Fächer, Gurte, Verschlüsse und Farbe prüfen.`},{name:`Balenciaga-Steppjacke`,category:`Jacken`,description:`Visueller Eintrag für eine Balenciaga-gekennzeichnete Steppjacke. Maße, Verschlüsse, Paneele und Füllverteilung vergleichen.`},{name:`Winterjacke mit Kapuze`,category:`Jacken`,description:`Visueller Eintrag für eine Winterjacke mit Kapuze. Größe, Farbe, Maße, Kapuze, Verschlüsse, Taschen und Verarbeitung prüfen.`}],fr:[{name:`Masque de ski`,category:`Lunettes`,description:`Entrée visuelle pour des lunettes de ski. Confirmez écran, monture, pièces incluses et disponibilité sur la fiche actuelle.`},{name:`Chapeau Gucci`,category:`Couvre-chefs`,description:`Entrée visuelle pour un chapeau étiqueté Gucci. Vérifiez option, mesures, construction et données actuelles sans vous fier uniquement à l'image.`},{name:`Sweats à capuche Off-White`,category:`Sweats`,description:`Entrée visuelle pour des sweats étiquetés Off-White. Vérifiez motif, mesures, placement de l'impression et variante actuelle.`},{name:`Chaussures montantes Numeris`,category:`Chaussures`,description:`Entrée visuelle pour des chaussures montantes Numeris. Confirmez taille et couleur puis contrôlez la paire reçue avec mesures et photos QC.`},{name:`HOKA Speedgoat 5`,category:`Chaussures`,description:`Entrée visuelle pour une chaussure étiquetée HOKA Speedgoat 5. Confirmez option, taille et fiche puis comparez les deux chaussures au QC.`},{name:`Sac à dos Nike Elite`,category:`Sacs`,description:`Entrée visuelle pour un sac à dos étiqueté Nike Elite. Confirmez dimensions, compartiments, sangles, fermetures et couleur.`},{name:`Doudoune Balenciaga`,category:`Vestes`,description:`Entrée visuelle pour une doudoune étiquetée Balenciaga. Comparez mesures, fermetures, panneaux et répartition du rembourrage.`},{name:`Veste d’hiver à capuche`,category:`Vestes`,description:`Entrée visuelle pour une veste d'hiver à capuche. Vérifiez taille, couleur, mesures, capuche, fermetures, poches et construction.`}],it:[{name:`Maschera da sci`,category:`Occhiali`,description:`Voce visiva per occhiali da sci. Conferma lente, montatura, pezzi inclusi e disponibilità nella scheda attuale.`},{name:`Cappello Gucci`,category:`Copricapi`,description:`Voce visiva per un cappello con etichetta Gucci. Verifica opzione, misure, costruzione e dati attuali senza basarti solo sull'immagine.`},{name:`Felpe con cappuccio Off-White`,category:`Felpe`,description:`Voce visiva per felpe con etichetta Off-White. Controlla design, misure, posizione della stampa e variante attuale.`},{name:`Scarpe alte Numeris`,category:`Scarpe`,description:`Voce visiva per scarpe alte Numeris. Conferma taglia e colore e usa misure e foto QC per controllare la coppia ricevuta.`},{name:`HOKA Speedgoat 5`,category:`Scarpe`,description:`Voce visiva per una scarpa con etichetta HOKA Speedgoat 5. Conferma opzione, taglia e scheda e confronta entrambe le scarpe nel QC.`},{name:`Zaino Nike Elite`,category:`Borse`,description:`Voce visiva per uno zaino con etichetta Nike Elite. Conferma dimensioni, scomparti, cinturini, chiusure e colore.`},{name:`Piumino Balenciaga`,category:`Giacche`,description:`Voce visiva per un piumino con etichetta Balenciaga. Confronta misure, chiusure, pannelli e distribuzione dell'imbottitura.`},{name:`Giacca invernale con cappuccio`,category:`Giacche`,description:`Voce visiva per una giacca invernale con cappuccio. Verifica taglia, colore, misure, cappuccio, chiusure, tasche e costruzione.`}]};function m(e){return e===`en`?u:u.map((t,n)=>({...t,...p[e][n]}))}var h={es:[{question:`¿Qué es un spreadsheet de Lolobuy?`,basis:`DIRECTORIO INDEPENDIENTE`,answer:`Es un directorio independiente que agrupa enlaces, categorías y orientación práctica. Sirve para descubrir productos, no sustituye la ficha actual ni demuestra stock, fiabilidad del vendedor o aprobación QC.`},{question:`¿Lolobuy Sheet es una web oficial de Lolobuy?`,basis:`DIRECTORIO INDEPENDIENTE`,answer:`No. Es un sitio independiente y no pertenece ni está respaldado por LoloBuy. Los datos de servicio se revisaron con información pública, pero la cuenta actual controla cada pedido.`},{question:`¿Este sitio vende, almacena o envía productos?`,basis:`DIRECTORIO INDEPENDIENTE`,answer:`No. Organiza productos y explica el proceso; no cobra, compra, inspecciona ni envía. Los pedidos, fotos, devoluciones, cotizaciones y seguimiento pertenecen al servicio que gestiona la transacción.`},{question:`¿Qué afirma oficialmente LoloBuy sobre su servicio de compra?`,basis:`CONFIRMADO EN LA WEB OFICIAL`,answer:`La página pública dice que ayuda a comprar en canales chinos online y offline y que se puede empezar pegando un enlace. Esto no garantiza que cada producto o vendedor sea aceptado.`},{question:`¿Cómo empieza un pedido LoloBuy con un enlace?`,basis:`CONFIRMADO EN LA WEB OFICIAL`,answer:`La página oficial indica que se pega el enlace del producto. Antes de pagar, confirma opción, talla, color, cantidad, precio y entrega nacional en la ficha y en el pedido generado.`},{question:`¿Qué enlaces de producto se pueden enviar?`,basis:`AFIRMACIÓN OFICIAL CON LÍMITE`,answer:`La web usa una descripción amplia de canales chinos, pero no publica una lista completa de marketplaces o categorías garantizadas. Comprueba que el pedido reconoce el enlace y cualquier restricción antes de pagar.`},{question:`¿Se verifican manualmente todos los enlaces cada día?`,basis:`POLÍTICA DEL DIRECTORIO`,answer:`No hacemos esa afirmación. Una ficha puede cambiar, agotarse o desaparecer sin aviso; abre la página actual y revisa variante, precio y disponibilidad antes de pedir.`},{question:`¿Qué ocurre cuando el vendedor envía el artículo al almacén?`,basis:`CONFIRMADO EN LA WEB OFICIAL`,answer:`LoloBuy declara que el almacén realiza control de calidad, toma fotografías y ofrece 90 días de almacenamiento gratuito. No publica allí la lista completa de inspección, cantidad de fotos o solución para cada defecto.`},{question:`¿Qué significa QC en un pedido LoloBuy?`,basis:`PROCESO DE ALMACÉN EXPLICADO`,answer:`QC significa control de calidad. Las fotos permiten comparar el artículo recibido con el pedido: tipo, color, talla, cantidad, daños y detalles visibles. No prueban composición, duración o autenticidad.`},{question:`¿Cuántas fotos QC gratuitas ofrece LoloBuy?`,basis:`NO PUBLICADO EN LA WEB OFICIAL`,answer:`La web confirma fotografías, pero no una cantidad universal gratuita. Revisa el conjunto real de imágenes del pedido y solicita un ángulo o medida concreta si la cuenta ofrece esa opción.`},{question:`¿LoloBuy ofrece fotos extra o vídeo de almacén?`,basis:`NO PUBLICADO EN LA WEB OFICIAL`,answer:`La página pública revisada no fija ese servicio, cantidad o precio. Comprueba las opciones actuales de la cuenta o pregunta a soporte antes de depender de una foto o vídeo adicional.`},{question:`¿Cuánto dura el almacenamiento gratuito de LoloBuy?`,basis:`CONFIRMADO EN LA WEB OFICIAL`,answer:`La web anuncia 90 días gratuitos. No explica públicamente todos los detalles del inicio del plazo o de lo que ocurre después; registra la fecha de llegada de cada artículo y actúa con margen.`},{question:`¿Se pueden combinar varios pedidos en un paquete?`,basis:`NO PUBLICADO EN LA WEB OFICIAL`,answer:`La página pública confirma almacenamiento, pero no una política completa de consolidación. Comprueba en el flujo actual si los artículos son compatibles y si restricciones, tamaño o protección exigen dividirlos.`},{question:`¿Cuánto cuesta el envío internacional de LoloBuy?`,basis:`SIN PRECIO FIJO PUBLICADO`,answer:`No existe un precio único público para todos los pedidos. El coste depende de destino, peso y dimensiones preparados, ruta elegible, restricciones y cargos actuales. Decide con la cotización del paquete real.`},{question:`¿LoloBuy garantiza plazos, transportistas o seguimiento?`,basis:`NO PUBLICADO EN LA WEB OFICIAL`,answer:`La página pública no ofrece una tabla permanente completa ni garantías universales. Compara solo las rutas disponibles para tu paquete y distingue una estimación de una garantía.`},{question:`¿LoloBuy publica una comisión fija o recargo de cambio?`,basis:`NO PUBLICADO EN LA WEB OFICIAL`,answer:`La página revisada no muestra un porcentaje universal. Separa precio del vendedor, entrega nacional, servicios opcionales, pago, cambio de divisa y transporte internacional en el desglose actual.`},{question:`¿Por qué cambia el precio al abrir un enlace del spreadsheet?`,basis:`COMPROBACIÓN PRÁCTICA`,answer:`El vendedor controla la ficha. El precio inicial puede corresponder a otra variante, accesorio o depósito, y también puede cambiar el stock. Selecciona la opción exacta y compara el pedido antes de pagar.`},{question:`¿Cuáles son las reglas de devolución o cambio tras el QC?`,basis:`NO PUBLICADO EN LA WEB OFICIAL`,answer:`La página pública no detalla una política completa, plazo o tarifas. Revisa las fotos rápido, conserva la opción pedida y usa la acción disponible en ese pedido antes del envío internacional.`},{question:`¿Los cupones y descuentos de envío son permanentes?`,basis:`SIN OFERTA PERMANENTE PUBLICADA`,answer:`No hay un valor universal permanente publicado. Una promoción puede depender de cuenta, ruta, destino, gasto y fecha; solo considérala válida cuando el checkout la acepte y muestre el total reducido.`},{question:`¿Qué significa W2C en un spreadsheet de Lolobuy?`,basis:`TÉRMINO DEL DIRECTORIO`,answer:`W2C suele significar “where to cop”, el enlace para localizar un producto. No prueba que la ficha esté vigente o sea adecuada; verifica opción, precio y restricciones y guarda el enlace con el pedido.`},{question:`¿Qué debo revisar en las fotos QC del almacén?`,basis:`LISTA QC PRÁCTICA`,answer:`Confirma primero producto, color, talla y cantidad; después daños, piezas faltantes y variante; por último forma, costuras, estampado y medidas. Compara con la ficha guardada, no con la memoria.`},{question:`¿Un spreadsheet o foto QC garantiza autenticidad o legalidad de importación?`,basis:`LÍMITE IMPORTANTE`,answer:`No. Una imagen solo ayuda a comparar aspectos visibles. No demuestra autenticidad, composición, certificación o legalidad en cada país; confirma restricciones de ruta y obligaciones aduaneras aplicables.`}],de:[{question:`Was ist ein Lolobuy Spreadsheet?`,basis:`UNABHÄNGIGES VERZEICHNIS`,answer:`Es ist ein unabhängiges Verzeichnis für Produktlinks, Kategorien und praktische Hinweise. Es hilft bei der Suche, ersetzt aber weder das Live-Angebot noch beweist es Bestand, Verkäuferzuverlässigkeit oder bestandene QC-Prüfung.`},{question:`Ist Lolobuy Sheet eine offizielle Lolobuy-Website?`,basis:`UNABHÄNGIGES VERZEICHNIS`,answer:`Nein. Die Seite ist unabhängig und gehört nicht zu LoloBuy. Öffentliche Leistungsangaben wurden geprüft, für den Auftrag gilt jedoch das aktuelle Konto.`},{question:`Verkauft, lagert oder versendet diese Seite Produkte?`,basis:`UNABHÄNGIGES VERZEICHNIS`,answer:`Nein. Sie ordnet Produkte und erklärt Abläufe, nimmt aber kein Geld an, kauft nicht ein, prüft nicht und versendet nicht. Auftrag, Fotos, Rückgabe, Angebot und Tracking gehören zum ausführenden Dienst.`},{question:`Was sagt LoloBuy offiziell über seinen Einkaufsservice?`,basis:`AUF OFFIZIELLER WEBSITE BESTÄTIGT`,answer:`Die öffentliche Seite beschreibt Hilfe bei Käufen über chinesische Online- und Offline-Kanäle und den Start per Produktlink. Damit ist nicht jeder Artikel oder Verkäufer garantiert.`},{question:`Wie beginnt eine LoloBuy-Bestellung per Link?`,basis:`AUF OFFIZIELLER WEBSITE BESTÄTIGT`,answer:`Laut Website wird der Produktlink eingefügt. Vor der Zahlung Option, Größe, Farbe, Menge, Preis und Inlandsversand im Angebot und im erzeugten Auftrag vergleichen.`},{question:`Welche Produktlinks können eingereicht werden?`,basis:`OFFIZIELLE AUSSAGE MIT GRENZE`,answer:`Die Seite spricht allgemein von chinesischen Kanälen, veröffentlicht aber keine vollständige garantierte Marktplatz- oder Kategorienliste. Erkennung und Einschränkungen vor der Zahlung prüfen.`},{question:`Werden alle Links täglich manuell geprüft?`,basis:`VERZEICHNISRICHTLINIE`,answer:`Nein, das behaupten wir nicht. Angebote können sich ändern, ausverkauft sein oder verschwinden. Variante, Preis und Bestand unmittelbar vor der Bestellung prüfen.`},{question:`Was geschieht nach dem Versand zum LoloBuy-Lager?`,basis:`AUF OFFIZIELLER WEBSITE BESTÄTIGT`,answer:`LoloBuy nennt Qualitätsprüfung, Fotos und 90 Tage kostenlose Lagerung. Eine vollständige Prüfliste, Fotozahl oder Lösung für jeden Mangel wird dort nicht veröffentlicht.`},{question:`Was bedeutet QC bei einer LoloBuy-Bestellung?`,basis:`LAGERPROZESS ERKLÄRT`,answer:`QC bedeutet Qualitätskontrolle. Fotos helfen beim Abgleich von Artikel, Farbe, Größe, Menge, Schäden und sichtbaren Details. Material, Haltbarkeit oder Echtheit beweisen sie nicht.`},{question:`Wie viele kostenlose QC-Fotos gibt es?`,basis:`NICHT AUF DER OFFIZIELLEN WEBSITE VERÖFFENTLICHT`,answer:`Fotos werden bestätigt, eine allgemeine kostenlose Anzahl jedoch nicht. Das tatsächliche Bildset prüfen und bei verfügbarer Option gezielt einen Blickwinkel oder ein Maß anfragen.`},{question:`Bietet LoloBuy Zusatzfotos oder Lagervideos?`,basis:`NICHT AUF DER OFFIZIELLEN WEBSITE VERÖFFENTLICHT`,answer:`Die geprüfte öffentliche Seite nennt keinen dauerhaften Dienst, Umfang oder Preis. Aktuelle Kontooptionen oder Support vorab prüfen.`},{question:`Wie lange ist die Lagerung kostenlos?`,basis:`AUF OFFIZIELLER WEBSITE BESTÄTIGT`,answer:`Die Website wirbt mit 90 kostenlosen Tagen. Details zum Fristbeginn und danach sind öffentlich nicht vollständig erklärt; Ankunftsdatum je Artikel notieren und früh handeln.`},{question:`Können mehrere Bestellungen gebündelt werden?`,basis:`NICHT AUF DER OFFIZIELLEN WEBSITE VERÖFFENTLICHT`,answer:`Die öffentliche Seite bestätigt Lagerung, aber keine vollständige Bündelungsrichtlinie. Im aktuellen Paketablauf Kompatibilität, Größe, Schutz und Einschränkungen prüfen.`},{question:`Was kostet internationaler LoloBuy-Versand?`,basis:`KEIN FESTPREIS VERÖFFENTLICHT`,answer:`Es gibt keinen öffentlichen Einheitspreis. Ziel, Packgewicht, Maße, zulässige Route, Einschränkungen und aktuelle Gebühren bestimmen den Betrag. Das reale Paketangebot ist maßgeblich.`},{question:`Garantiert LoloBuy Laufzeit, Frachtführer oder Tracking?`,basis:`NICHT AUF DER OFFIZIELLEN WEBSITE VERÖFFENTLICHT`,answer:`Die öffentliche Seite bietet keine dauerhafte vollständige Tabelle oder allgemeine Garantie. Nur aktuell angebotene Routen vergleichen und Schätzung von Garantie unterscheiden.`},{question:`Veröffentlicht LoloBuy eine feste Servicegebühr oder Wechselkursmarge?`,basis:`NICHT AUF DER OFFIZIELLEN WEBSITE VERÖFFENTLICHT`,answer:`Ein allgemeiner Prozentsatz ist dort nicht genannt. Verkäuferpreis, China-Versand, Zusatzleistungen, Zahlung, Umrechnung und internationalen Versand im aktuellen Kostenblatt trennen.`},{question:`Warum ändert sich der Preis eines Spreadsheet-Links?`,basis:`PRAKTISCHE ANGEBOTSPRÜFUNG`,answer:`Der Verkäufer kontrolliert das Angebot. Der Startpreis kann zu einer anderen Variante, einem Zubehör oder einer Anzahlung gehören; auch Bestand kann sich ändern. Exakte Option auswählen und Auftrag vor Zahlung vergleichen.`},{question:`Welche Rückgabe- oder Umtauschregeln gelten nach QC?`,basis:`NICHT AUF DER OFFIZIELLEN WEBSITE VERÖFFENTLICHT`,answer:`Eine vollständige Richtlinie, Frist und Gebührentabelle steht nicht auf der öffentlichen Seite. Fotos zügig prüfen, Bestellnachweis sichern und die aktuelle Auftragsfunktion vor Auslandsversand nutzen.`},{question:`Sind Gutscheine und Versandrabatte dauerhaft?`,basis:`KEIN DAUERHAFTES ANGEBOT VERÖFFENTLICHT`,answer:`Ein allgemeiner dauerhafter Wert ist nicht veröffentlicht. Aktion erst als gültig behandeln, wenn der aktuelle Checkout sie annimmt und den reduzierten Gesamtbetrag zeigt.`},{question:`Was bedeutet W2C in einem Lolobuy Spreadsheet?`,basis:`BEGRIFF DES VERZEICHNISSES`,answer:`W2C bedeutet meist „where to cop“, also der Link zum Produkt. Er beweist weder Aktualität noch Eignung. Option, Preis, Einschränkungen prüfen und den Link beim Auftrag speichern.`},{question:`Was sollte ich in Lager-QC-Fotos prüfen?`,basis:`PRAKTISCHE QC-CHECKLISTE`,answer:`Zuerst Artikel, Farbe, Größe und Menge; dann Schäden, fehlende Teile und falsche Variante; zuletzt Form, Nähte, Druck und Maße. Mit dem gespeicherten Angebot statt aus Erinnerung vergleichen.`},{question:`Garantiert ein Spreadsheet oder QC-Foto Echtheit oder legale Einfuhr?`,basis:`WICHTIGE GRENZE`,answer:`Nein. Bilder helfen nur beim sichtbaren Vergleich. Sie beweisen weder Echtheit, Zusammensetzung, Zertifizierung noch Einfuhrrecht; Routenbeschränkungen und Zollpflichten selbst prüfen.`}],fr:[{question:`Qu'est-ce qu'un spreadsheet Lolobuy ?`,basis:`CATALOGUE INDÉPENDANT`,answer:`C'est un catalogue indépendant de liens, catégories et conseils pratiques. Il aide à découvrir sans remplacer la fiche actuelle ni prouver stock, fiabilité vendeur ou validation QC.`},{question:`Lolobuy Sheet est-il un site officiel Lolobuy ?`,basis:`CATALOGUE INDÉPENDANT`,answer:`Non. Le site est indépendant et n'appartient pas à LoloBuy. Les informations de service reposent sur des sources publiques, mais le compte actuel contrôle chaque commande.`},{question:`Ce site vend-il, stocke-t-il ou expédie-t-il des produits ?`,basis:`CATALOGUE INDÉPENDANT`,answer:`Non. Il organise des produits et explique le parcours ; il n'encaisse pas, n'achète pas, n'inspecte pas et n'expédie pas. Commande, photos, retour, devis et suivi relèvent du service qui traite la transaction.`},{question:`Que dit officiellement LoloBuy sur son service d'achat ?`,basis:`CONFIRMÉ SUR LE SITE OFFICIEL`,answer:`La page publique indique une assistance pour les achats via des canaux chinois en ligne et hors ligne, avec un démarrage par lien produit. Cela ne garantit pas chaque article ou vendeur.`},{question:`Comment une commande LoloBuy commence-t-elle avec un lien ?`,basis:`CONFIRMÉ SUR LE SITE OFFICIEL`,answer:`Le site indique de coller le lien produit. Avant paiement, comparez option, taille, couleur, quantité, prix et livraison locale entre la fiche et la commande générée.`},{question:`Quels liens produit peuvent être soumis ?`,basis:`AFFIRMATION OFFICIELLE AVEC LIMITE`,answer:`Le site parle largement de canaux chinois, sans publier de liste complète de marketplaces ou catégories garanties. Vérifiez la lecture du lien et les restrictions avant de payer.`},{question:`Tous les liens sont-ils vérifiés manuellement chaque jour ?`,basis:`RÈGLE DU CATALOGUE`,answer:`Non, nous ne faisons pas cette promesse. Une fiche peut changer, être épuisée ou disparaître ; vérifiez variante, prix et disponibilité juste avant de commander.`},{question:`Que se passe-t-il après l'envoi au dépôt LoloBuy ?`,basis:`CONFIRMÉ SUR LE SITE OFFICIEL`,answer:`LoloBuy annonce contrôle qualité, photos et 90 jours de stockage gratuit. La liste d'inspection, le nombre de photos et le recours pour chaque défaut ne sont pas détaillés publiquement.`},{question:`Que signifie QC dans une commande LoloBuy ?`,basis:`PROCESSUS D'ENTREPÔT EXPLIQUÉ`,answer:`QC signifie contrôle qualité. Les photos servent à comparer article, couleur, taille, quantité, dommages et détails visibles. Elles ne prouvent ni composition, ni durabilité, ni authenticité.`},{question:`Combien de photos QC gratuites LoloBuy fournit-il ?`,basis:`NON PUBLIÉ SUR LE SITE OFFICIEL`,answer:`Les photos sont confirmées, pas un nombre universel gratuit. Examinez le lot réel et demandez un angle ou une mesure précise si le compte propose cette option.`},{question:`LoloBuy propose-t-il des photos supplémentaires ou une vidéo ?`,basis:`NON PUBLIÉ SUR LE SITE OFFICIEL`,answer:`La page publique vérifiée ne fixe ni service permanent, ni quantité, ni tarif. Contrôlez les options actuelles du compte ou demandez au support.`},{question:`Combien de temps le stockage LoloBuy est-il gratuit ?`,basis:`CONFIRMÉ SUR LE SITE OFFICIEL`,answer:`Le site annonce 90 jours gratuits. Le début exact et les suites ne sont pas entièrement détaillés publiquement ; notez la date d'arrivée de chaque article et gardez une marge.`},{question:`Plusieurs commandes peuvent-elles être regroupées ?`,basis:`NON PUBLIÉ SUR LE SITE OFFICIEL`,answer:`La page confirme le stockage, mais pas une politique complète de consolidation. Vérifiez dans le flux actuel compatibilité, taille, protection et restrictions.`},{question:`Combien coûte l'expédition internationale LoloBuy ?`,basis:`AUCUN PRIX FIXE PUBLIÉ`,answer:`Il n'existe pas de prix public unique. Destination, poids et dimensions emballés, route admissible, restrictions et frais actuels déterminent le coût. Le devis du colis réel fait foi.`},{question:`LoloBuy garantit-il délais, transporteurs ou suivi ?`,basis:`NON PUBLIÉ SUR LE SITE OFFICIEL`,answer:`La page publique ne donne pas de tableau permanent complet ni de garantie générale. Comparez les routes réellement proposées et distinguez estimation et garantie.`},{question:`LoloBuy publie-t-il des frais fixes ou une marge de change ?`,basis:`NON PUBLIÉ SUR LE SITE OFFICIEL`,answer:`Aucun pourcentage universel n'est indiqué. Séparez prix vendeur, livraison chinoise, services, paiement, conversion et fret international dans le détail actuel.`},{question:`Pourquoi le prix change-t-il après l'ouverture d'un lien ?`,basis:`VÉRIFICATION PRATIQUE`,answer:`Le vendeur contrôle la fiche. Le prix d'appel peut viser une autre variante, un accessoire ou un acompte et le stock peut changer. Sélectionnez l'option exacte et comparez avant paiement.`},{question:`Quelles règles de retour ou d'échange après QC ?`,basis:`NON PUBLIÉ SUR LE SITE OFFICIEL`,answer:`La page publique ne détaille ni politique complète, ni délai, ni frais. Examinez rapidement les photos, conservez la variante commandée et utilisez l'action disponible avant l'expédition.`},{question:`Coupons et remises d'expédition sont-ils permanents ?`,basis:`AUCUNE OFFRE PERMANENTE PUBLIÉE`,answer:`Aucune valeur universelle permanente n'est publiée. Une promotion n'est valable que lorsque le checkout actuel l'accepte et affiche le total réduit.`},{question:`Que signifie W2C dans un spreadsheet Lolobuy ?`,basis:`TERME DU CATALOGUE`,answer:`W2C signifie généralement « where to cop », le lien vers le produit. Il ne prouve ni actualité ni admissibilité ; vérifiez option, prix, restrictions et conservez le lien avec la commande.`},{question:`Que vérifier dans les photos QC de l'entrepôt ?`,basis:`LISTE QC PRATIQUE`,answer:`D'abord article, couleur, taille et quantité ; ensuite dommages, pièces manquantes et variante ; enfin forme, coutures, motif et mesures. Comparez à la fiche sauvegardée.`},{question:`Un spreadsheet ou une photo QC garantit-il authenticité ou légalité ?`,basis:`LIMITE IMPORTANTE`,answer:`Non. Une image sert uniquement à comparer le visible. Elle ne prouve ni authenticité, composition, certification ou légalité d'importation ; vérifiez restrictions et obligations douanières.`}],it:[{question:`Cos'è uno spreadsheet Lolobuy?`,basis:`CATALOGO INDIPENDENTE`,answer:`È un catalogo indipendente di link, categorie e consigli pratici. Aiuta a scoprire prodotti ma non sostituisce la scheda attuale né prova disponibilità, affidabilità del venditore o QC superato.`},{question:`Lolobuy Sheet è un sito ufficiale Lolobuy?`,basis:`CATALOGO INDIPENDENTE`,answer:`No. Il sito è indipendente e non appartiene a LoloBuy. I dati di servizio derivano da fonti pubbliche, ma l'account attuale controlla ogni ordine.`},{question:`Questo sito vende, conserva o spedisce prodotti?`,basis:`CATALOGO INDIPENDENTE`,answer:`No. Organizza prodotti e spiega il percorso; non incassa, acquista, ispeziona o spedisce. Ordini, foto, resi, preventivi e tracking appartengono al servizio che gestisce la transazione.`},{question:`Cosa dichiara ufficialmente LoloBuy sul servizio d'acquisto?`,basis:`CONFERMATO SUL SITO UFFICIALE`,answer:`La pagina pubblica dice di assistere acquisti da canali cinesi online e offline e di iniziare tramite link prodotto. Non garantisce ogni articolo o venditore.`},{question:`Come inizia un ordine LoloBuy con un link?`,basis:`CONFERMATO SUL SITO UFFICIALE`,answer:`Il sito indica di incollare il link prodotto. Prima del pagamento confronta opzione, taglia, colore, quantità, prezzo e consegna nazionale tra scheda e ordine generato.`},{question:`Quali link prodotto si possono inviare?`,basis:`AFFERMAZIONE UFFICIALE CON LIMITE`,answer:`Il sito parla in modo ampio di canali cinesi ma non pubblica una lista completa garantita di marketplace o categorie. Verifica riconoscimento e restrizioni prima di pagare.`},{question:`Tutti i link sono verificati manualmente ogni giorno?`,basis:`POLITICA DEL CATALOGO`,answer:`No, non facciamo questa promessa. Una scheda può cambiare, esaurirsi o scomparire; controlla variante, prezzo e disponibilità subito prima dell'ordine.`},{question:`Cosa succede dopo l'invio al magazzino LoloBuy?`,basis:`CONFERMATO SUL SITO UFFICIALE`,answer:`LoloBuy dichiara controllo qualità, foto e 90 giorni di deposito gratuito. Non pubblica lì lista completa, numero di foto o rimedio per ogni difetto.`},{question:`Cosa significa QC in un ordine LoloBuy?`,basis:`PROCESSO DI MAGAZZINO SPIEGATO`,answer:`QC significa controllo qualità. Le foto aiutano a confrontare articolo, colore, taglia, quantità, danni e dettagli visibili. Non provano composizione, durata o autenticità.`},{question:`Quante foto QC gratuite offre LoloBuy?`,basis:`NON PUBBLICATO SUL SITO UFFICIALE`,answer:`Le foto sono confermate, non un numero universale gratuito. Controlla il set reale e richiedi un angolo o una misura specifica se l'account lo consente.`},{question:`LoloBuy offre foto extra o video di magazzino?`,basis:`NON PUBBLICATO SUL SITO UFFICIALE`,answer:`La pagina pubblica verificata non fissa servizio, quantità o prezzo permanente. Controlla le opzioni attuali o chiedi al supporto.`},{question:`Quanto dura il deposito gratuito LoloBuy?`,basis:`CONFERMATO SUL SITO UFFICIALE`,answer:`Il sito pubblicizza 90 giorni gratuiti. Inizio e conseguenze non sono spiegati completamente; registra la data d'arrivo di ogni articolo e agisci con anticipo.`},{question:`Si possono unire più ordini in un pacco?`,basis:`NON PUBBLICATO SUL SITO UFFICIALE`,answer:`La pagina conferma il deposito ma non una politica completa di consolidamento. Verifica nel flusso attuale compatibilità, dimensioni, protezione e restrizioni.`},{question:`Quanto costa la spedizione internazionale LoloBuy?`,basis:`NESSUN PREZZO FISSO PUBBLICATO`,answer:`Non esiste un prezzo pubblico unico. Destinazione, peso e dimensioni imballati, rotta idonea, restrizioni e addebiti attuali determinano il costo. Vale il preventivo del pacco reale.`},{question:`LoloBuy garantisce tempi, vettori o tracking?`,basis:`NON PUBBLICATO SUL SITO UFFICIALE`,answer:`La pagina pubblica non offre una tabella permanente completa o garanzie universali. Confronta solo le rotte effettivamente disponibili e distingui stima da garanzia.`},{question:`LoloBuy pubblica una commissione fissa o margine di cambio?`,basis:`NON PUBBLICATO SUL SITO UFFICIALE`,answer:`Non è indicata una percentuale universale. Separa prezzo venditore, consegna in Cina, servizi, pagamento, cambio e spedizione internazionale nel riepilogo attuale.`},{question:`Perché il prezzo cambia dopo aver aperto un link?`,basis:`CONTROLLO PRATICO`,answer:`Il venditore controlla la scheda. Il prezzo iniziale può riferirsi a un'altra variante, accessorio o deposito e lo stock può cambiare. Seleziona l'opzione esatta e confronta prima di pagare.`},{question:`Quali regole di reso o cambio valgono dopo il QC?`,basis:`NON PUBBLICATO SUL SITO UFFICIALE`,answer:`La pagina pubblica non dettaglia politica completa, scadenza o tariffe. Controlla presto le foto, conserva la variante ordinata e usa l'azione disponibile prima della spedizione.`},{question:`Coupon e sconti di spedizione sono permanenti?`,basis:`NESSUNA OFFERTA PERMANENTE PUBBLICATA`,answer:`Non è pubblicato un valore universale permanente. Considera valida una promozione solo quando il checkout attuale la accetta e mostra il totale ridotto.`},{question:`Cosa significa W2C in uno spreadsheet Lolobuy?`,basis:`TERMINE DEL CATALOGO`,answer:`W2C significa di solito “where to cop”, il link per trovare il prodotto. Non prova attualità o idoneità; verifica opzione, prezzo, restrizioni e conserva il link nell'ordine.`},{question:`Cosa devo controllare nelle foto QC del magazzino?`,basis:`LISTA QC PRATICA`,answer:`Prima articolo, colore, taglia e quantità; poi danni, pezzi mancanti e variante; infine forma, cuciture, stampa e misure. Confronta con la scheda salvata.`},{question:`Uno spreadsheet o una foto QC garantisce autenticità o legalità?`,basis:`LIMITE IMPORTANTE`,answer:`No. Un'immagine aiuta solo nel confronto visibile. Non prova autenticità, composizione, certificazione o legalità d'importazione; verifica restrizioni e obblighi doganali.`}]};function g(e){return e===`en`?f:f.map((t,n)=>({...t,...h[e][n]}))}var _={es:[{title:`Guía del spreadsheet Lolobuy 2026: cómo usar un directorio sin saltarse la verificación`,shortTitle:`Cómo usar con cuidado un spreadsheet Lolobuy`,description:`Guía práctica para descubrir productos, comprobar fichas, leer el QC y evitar decisiones apresuradas.`,eyebrow:`BASES DEL SPREADSHEET`,readingTime:`13 min de lectura`,factCheckLine:`Verificado con la web pública de LoloBuy y la guía comunitaria disponible el 26 de julio de 2026.`},{title:`Cómo leer fotos QC de almacén: lista práctica para ropa, calzado y bolsos`,shortTitle:`Cómo leer las fotos QC del almacén`,description:`Una lista repetible para revisar identidad, medidas, simetría, daños visibles y límites de las fotos.`,eyebrow:`GUÍA QC`,readingTime:`12 min de lectura`,factCheckLine:`Verificado con la descripción pública de inspección y fotografías de LoloBuy el 26 de julio de 2026.`},{title:`Cómo planificar un haul de China: almacenamiento, consolidación, peso y rutas`,shortTitle:`Planificar almacenamiento, paquete y envío`,description:`Guía para estimar costes, entender peso real y volumétrico y elegir una ruta con los datos finales.`,eyebrow:`PLANIFICACIÓN DEL PAQUETE`,readingTime:`12 min de lectura`,factCheckLine:`Verificado con la información pública de almacenamiento y el flujo de pedido disponible el 26 de julio de 2026.`},{title:`Reseña de LoloBuy 2026: qué demuestra realmente una experiencia temprana`,shortTitle:`Una reseña temprana de LoloBuy, examinada`,description:`Análisis prudente de una experiencia inicial, separando pruebas de compra y almacén de lo que aún no se ha probado.`,eyebrow:`ANÁLISIS DE EXPERIENCIA`,readingTime:`11 min de lectura`,factCheckLine:`La experiencia se evaluó como un caso individual y preliminar; no como una puntuación universal.`}],de:[{title:`Lolobuy Spreadsheet Ratgeber 2026: Produktverzeichnisse mit Prüfung nutzen`,shortTitle:`Ein Lolobuy Spreadsheet sorgfältig verwenden`,description:`Praktischer Ratgeber zu Produktsuche, Live-Angebot, QC und überlegten Kaufentscheidungen.`,eyebrow:`SPREADSHEET-GRUNDLAGEN`,readingTime:`13 Min. Lesezeit`,factCheckLine:`Abgeglichen mit LoloBuy-Website und öffentlichem Community-Leitfaden am 26. Juli 2026.`},{title:`Lager-QC-Fotos lesen: Checkliste für Kleidung, Schuhe und Taschen`,shortTitle:`Lager-QC-Fotos richtig lesen`,description:`Wiederholbare Checkliste für Identität, Maße, Symmetrie, sichtbare Schäden und Bildgrenzen.`,eyebrow:`QC-PRAXIS`,readingTime:`12 Min. Lesezeit`,factCheckLine:`Mit LoloBuys öffentlicher Beschreibung von Prüfung und Fotos am 26. Juli 2026 abgeglichen.`},{title:`China-Haul planen: Lagerung, Bündelung, Gewicht und Routen`,shortTitle:`Lagerung, Paket und Versand planen`,description:`Ratgeber zu Kostenschätzung, Ist- und Volumengewicht und Routenwahl anhand finaler Paketdaten.`,eyebrow:`PAKETPLANUNG`,readingTime:`12 Min. Lesezeit`,factCheckLine:`Mit öffentlichen Lager- und Ablaufangaben vom 26. Juli 2026 abgeglichen.`},{title:`LoloBuy-Erfahrungsbericht 2026: Was ein früher Nutzerbericht wirklich zeigt`,shortTitle:`Ein früher LoloBuy-Bericht, geprüft`,description:`Vorsichtige Analyse eines frühen Berichts, getrennt nach belegtem Einkauf, Lagerphase und noch offenen Fragen.`,eyebrow:`ERFAHRUNGSANALYSE`,readingTime:`11 Min. Lesezeit`,factCheckLine:`Der Bericht wird als einzelner, vorläufiger Fall und nicht als allgemeine Bewertung behandelt.`}],fr:[{title:`Guide du spreadsheet Lolobuy 2026 : utiliser un catalogue sans négliger les vérifications`,shortTitle:`Bien utiliser un spreadsheet Lolobuy`,description:`Guide pratique pour découvrir, vérifier les fiches, lire le QC et éviter les décisions précipitées.`,eyebrow:`BASES DU SPREADSHEET`,readingTime:`13 min de lecture`,factCheckLine:`Vérifié avec le site public LoloBuy et le guide communautaire disponible le 26 juillet 2026.`},{title:`Lire les photos QC d'entrepôt : liste pratique pour vêtements, chaussures et sacs`,shortTitle:`Bien lire les photos QC d'entrepôt`,description:`Une liste reproductible pour contrôler identité, mesures, symétrie, dommages visibles et limites des photos.`,eyebrow:`GUIDE QC`,readingTime:`12 min de lecture`,factCheckLine:`Vérifié avec la description publique de l'inspection et des photos LoloBuy le 26 juillet 2026.`},{title:`Planifier un haul depuis la Chine : stockage, consolidation, poids et routes`,shortTitle:`Planifier stockage, colis et expédition`,description:`Guide pour estimer le coût, comprendre poids réel et volumétrique et choisir avec les données finales.`,eyebrow:`PLANIFICATION DU COLIS`,readingTime:`12 min de lecture`,factCheckLine:`Vérifié avec les informations publiques de stockage et de parcours disponibles le 26 juillet 2026.`},{title:`Avis LoloBuy 2026 : ce qu'une première expérience démontre réellement`,shortTitle:`Un premier avis LoloBuy examiné`,description:`Analyse prudente d'une première expérience, séparant les preuves d'achat et d'entrepôt des questions non testées.`,eyebrow:`ANALYSE D'EXPÉRIENCE`,readingTime:`11 min de lecture`,factCheckLine:`Le témoignage est traité comme un cas individuel préliminaire, pas comme une note universelle.`}],it:[{title:`Guida allo spreadsheet Lolobuy 2026: usare un catalogo senza saltare le verifiche`,shortTitle:`Usare con attenzione uno spreadsheet Lolobuy`,description:`Guida pratica per scoprire prodotti, controllare schede, leggere il QC ed evitare decisioni affrettate.`,eyebrow:`BASI DELLO SPREADSHEET`,readingTime:`13 min di lettura`,factCheckLine:`Verificato con il sito pubblico LoloBuy e la guida community disponibile il 26 luglio 2026.`},{title:`Come leggere le foto QC di magazzino: lista per abbigliamento, scarpe e borse`,shortTitle:`Leggere le foto QC del magazzino`,description:`Una lista ripetibile per identità, misure, simmetria, danni visibili e limiti delle immagini.`,eyebrow:`GUIDA QC`,readingTime:`12 min di lettura`,factCheckLine:`Verificato con la descrizione pubblica LoloBuy di ispezione e foto il 26 luglio 2026.`},{title:`Pianificare un haul dalla Cina: deposito, consolidamento, peso e rotte`,shortTitle:`Pianificare deposito, pacco e spedizione`,description:`Guida per stimare costi, capire peso reale e volumetrico e scegliere con i dati finali.`,eyebrow:`PIANIFICAZIONE DEL PACCO`,readingTime:`12 min di lettura`,factCheckLine:`Verificato con le informazioni pubbliche su deposito e flusso disponibili il 26 luglio 2026.`},{title:`Recensione LoloBuy 2026: cosa dimostra davvero una prima esperienza`,shortTitle:`Una prima recensione LoloBuy esaminata`,description:`Analisi prudente di una prima esperienza, separando prove di acquisto e magazzino dalle domande non testate.`,eyebrow:`ANALISI DELL'ESPERIENZA`,readingTime:`11 min di lettura`,factCheckLine:`Il resoconto è trattato come caso individuale preliminare, non come valutazione universale.`}]},v={es:[{visual:{eyebrow:`REGLA DE LAS CUATRO FUENTES`,title:`Una decisión, cuatro fuentes distintas.`,caption:`El directorio inicia la búsqueda; la ficha actual, las pruebas QC y el paquete preparado controlan etapas diferentes.`,items:[[`Directorio`,`Encuentra una idea y compara categorías.`],[`Ficha actual`,`Confirma vendedor, opción, precio y descripción.`],[`QC de almacén`,`Revisa el artículo físico recibido.`],[`Paquete preparado`,`Elige envío por peso, dimensiones y elegibilidad actuales.`]]},sources:[[`Web pública de LoloBuy`,`Declaraciones públicas sobre compra, inspección, fotos y 90 días de almacenamiento.`],[`Guía comunitaria de pedidos LoloBuy`,`Resumen público de las etapas del pedido en la comunidad identificada de la plataforma.`]],intro:[`Un spreadsheet útil reduce el tiempo entre una idea vaga y una ficha que puede evaluarse. Las categorías y la búsqueda ayudan a descubrir, pero no sustituyen la comprobación de vendedor, precio, opciones y restricciones.`,`Esta guía separa lo que puede aportar un directorio de lo que debe confirmarse en la ficha, las fotos QC o el paquete final.`],sections:[{heading:`Empieza por la intención, no por un feed infinito`,paragraphs:[`Define categoría, uso, material, medidas, colores aceptables y presupuesto antes de abrir muchos enlaces. Conserva dos o tres candidatos para comparar en lugar de decidir por la primera imagen.`],bullets:[`Define tipo y uso.`,`Anota medidas necesarias.`,`Separa precio del producto y coste total.`,`Compara varios candidatos.`]},{heading:`Trata cada entrada como una pista`,paragraphs:[`El vendedor controla fotos, stock, variantes, precio y descripción. Abre la ficha actual, selecciona la opción correcta y compara las medidas con una prenda propia antes de valorar el producto.`]},{heading:`Distingue lo que LoloBuy confirma públicamente`,paragraphs:[`La página pública describe compra por enlace, inspección y fotos al llegar al almacén y 90 días de almacenamiento gratuito. No publica una tarifa permanente, un plazo garantizado ni una cantidad universal de fotos; esos datos se revisan en la cuenta actual.`]},{heading:`Convierte el enlace en una nota de pedido`,paragraphs:[`Guarda URL, fecha, color, talla, cantidad, texto original de la opción, tabla de medidas y precio visible. Una nota precisa reduce errores cuando la traducción o las imágenes de variantes son ambiguas.`],bullets:[`URL y fecha`,`Opción exacta`,`Medidas clave`,`Precio y entrega nacional`,`Detalle no negociable`]},{heading:`Desconfía de afirmaciones sin pruebas`,paragraphs:[`“Verificado”, “más barato” o “actualizado a diario” necesitan evidencia. Una presencia en el directorio no demuestra fiabilidad, autenticidad o coste final, y una experiencia positiva no representa a toda la plataforma.`]},{heading:`Separa fotos del vendedor y fotos QC`,paragraphs:[`Las fotos del vendedor presentan la oferta; las fotos QC documentan el artículo recibido. Confirma primero identidad y variante, después construcción y daños, y pide una toma específica solo si cambia la decisión.`]},{heading:`Calcula un precio de decisión`,paragraphs:[`El coste incluye producto, entrega china, posibles servicios, envío internacional, embalaje e impuestos. Usa una estimación conservadora para planificar y la cotización del paquete preparado para decidir.`],bullets:[`Comprueba entrega nacional.`,`Estima peso y volumen.`,`Reserva margen para embalaje.`,`Revisa el total final.`]},{heading:`Conserva un registro breve`,paragraphs:[`Guarda enlace, opción, tabla, precio y fecha. Los marcadores ayudan a navegar, pero no garantizan que una ficha siga disponible; repite la revisión antes de pedir.`]},{heading:`La regla práctica`,paragraphs:[`Usa el spreadsheet para descubrir, la ficha actual para confirmar, las fotos QC para inspeccionar y el paquete final para elegir envío. Mantener esas etapas separadas evita promesas falsas.`]}]},{visual:{eyebrow:`ORDEN DE REVISIÓN QC`,title:`Revisa las pruebas en el orden correcto.`,caption:`Una secuencia tranquila evita que un detalle menor oculte una talla equivocada, una pieza ausente o un problema estructural.`,items:[[`Identidad`,`Producto, color, talla, cantidad y piezas.`],[`Estructura`,`Forma, simetría, alineación y daños.`],[`Medidas`,`Dimensiones críticas comparadas con una referencia.`],[`Acción`,`Aceptar, pedir una comprobación concreta o usar el recurso actual.`]]},sources:[[`Web pública de LoloBuy`,`Confirma inspección de calidad y fotografías tras la llegada al almacén.`],[`Informe independiente temprano`,`Un caso preliminar sobre fotos QC, diferencia de talla y respuesta de soporte; no es una puntuación representativa.`]],intro:[`Las fotos QC son más útiles con una lista. Una impresión general puede ocultar problemas; ampliar cada píxel puede crear falsas alarmas por luz, compresión o perspectiva.`,`El objetivo no es demostrar perfección, sino decidir con información si aceptar, cambiar o devolver dentro del proceso disponible.`],sections:[{heading:`Empieza por la identidad del pedido`,paragraphs:[`Confirma producto, color, modelo, talla, cantidad y piezas incluidas antes de mirar costuras. El embalaje solo debe esperarse si formaba parte de la oferta.`],bullets:[`Producto y color correctos`,`Talla o variante correcta`,`Cantidad y piezas correctas`,`Sin daños evidentes`]},{heading:`Mantén claro el límite de los datos públicos`,paragraphs:[`LoloBuy confirma inspección y fotos, pero no publica una cantidad universal gratuita ni un precio permanente para tomas o vídeos extra. Usa las imágenes reales del pedido y las opciones actuales.`]},{heading:`Revisa forma y simetría antes de detalles pequeños`,paragraphs:[`Compara hombros, mangas y cuello en ropa; ambos zapatos y suelas en calzado; silueta, asas y cierres en bolsos. Usa varios ángulos porque la perspectiva puede exagerar diferencias.`]},{heading:`Ten en cuenta luz, compresión y distancia`,paragraphs:[`La iluminación puede alterar negros y blancos, el gran angular deforma bordes y la compresión destruye texturas. Compara el mismo rasgo en varias imágenes y utiliza reglas o etiquetas como referencias.`]},{heading:`Usa medidas para responder dudas de ajuste`,paragraphs:[`Compara la colocación de la regla con la tabla del vendedor y una prenda propia. Acepta pequeñas diferencias manuales, pero solicita la medida exacta que decide el ajuste si falta.`]},{heading:`Pide una respuesta, no solo más fotos`,paragraphs:[`Indica característica, ángulo y referencia: longitud de plantilla, vista equivalente del par, ancho de pecho o primer plano del daño. Prioriza pruebas que puedan cambiar la decisión.`],bullets:[`Nombra el detalle.`,`Indica ángulo o comparación.`,`Describe la diferencia.`,`Pide evidencia útil para decidir.`]},{heading:`Lista para ropa`,paragraphs:[`Revisa cuello, cremallera, botones, estampado, bolsillos, costuras, manchas y agujeros. En pantalones mira cintura, tiro, forma de pierna y bajo.`]},{heading:`Lista para calzado, bolsos y accesorios`,paragraphs:[`En zapatos compara el par, suelas, pegamento y paneles. En bolsos revisa forma, esquinas, asas, correas, zip, forro y herrajes; usa medidas para accesorios pequeños.`]},{heading:`Entiende lo que las fotos no demuestran`,paragraphs:[`No prueban duración, composición exacta, comodidad, funcionamiento electrónico o autenticidad, ni muestran todas las partes internas. El color también depende de luz y pantalla.`]},{heading:`Guarda las pruebas antes de mover el paquete`,paragraphs:[`Conserva referencia, captura de la ficha, opción y fotos importantes. Anota fecha, imagen y solución pedida, pero no dejes que la documentación te haga perder una fecha límite.`]},{heading:`Decide con calma: aceptar o actuar`,paragraphs:[`Clasifica lo encontrado como variación normal, defecto cosmético aceptable o diferencia material. Después revisa plazo y recurso actual y comunica foto, ubicación y resultado deseado.`]}]},{visual:{eyebrow:`CAPAS DEL COSTE FINAL`,title:`El precio del producto es solo la primera línea.`,caption:`Separa estimaciones y cargos confirmados. La elección internacional solo es real cuando existe un paquete preparado.`,items:[[`Producto`,`Variante elegida al precio actual.`],[`Coste en China`,`Entrega nacional y cargos claramente mostrados.`],[`Paquete`,`Embalaje, peso, dimensiones y reglas de ruta.`],[`Destino`,`Transporte internacional e impuestos o aduanas aplicables.`]]},sources:[[`Web pública de LoloBuy`,`Declaraciones públicas de 90 días de almacenamiento y servicios de almacén.`],[`Guía comunitaria de pedidos`,`Describe consolidación, selección de ruta, pago internacional y seguimiento.`]],intro:[`Un haul no es más barato solo por viajar junto. Consolidar puede reducir cajas repetidas, pero volumen, restricciones y calendario siguen importando.`,`Los 90 días anunciados son una ventana de planificación, no una razón para esperar al último día. Confirma siempre el plazo de cada artículo.`],sections:[{heading:`Empieza por lo que LoloBuy publica`,paragraphs:[`Las fuentes públicas respaldan compra asistida, inspección, fotos, 90 días de almacenamiento y un flujo posterior de consolidación, ruta y seguimiento. No crean una tarifa permanente para tu paquete.`]},{heading:`Diseña el paquete primero en papel`,paragraphs:[`Lista peso, dimensiones, material y cuidado de cada artículo. Detecta mezclas problemáticas, como prendas voluminosas con calzado pesado o accesorios frágiles, y decide qué puede esperar.`]},{heading:`Mantén las estimaciones en rangos`,paragraphs:[`El peso del vendedor no es el peso embalado. Usa un rango bajo y alto y añade margen para despacho, entrega nacional, entrada, QC, embalaje, exportación y aduanas.`],bullets:[`Peso estimado bajo y alto`,`Embalaje probable`,`Compatibilidad o restricción`,`Fecha personal de envío`]},{heading:`Entiende peso real y volumétrico`,paragraphs:[`El real procede de la báscula; el volumétrico convierte dimensiones con una fórmula de la ruta. Puede cobrarse el mayor. Quitar cajas reduce volumen, pero también protección.`],bullets:[`Lo denso suele pagar peso real.`,`Lo ligero y voluminoso puede pagar volumen.`,`El embalaje cambia ambos.`,`Los datos del almacén son mejores que una suposición.`]},{heading:`Usa el almacenamiento como margen`,paragraphs:[`Permite esperar llegadas y resolver diferencias antes del envío. Registra la fecha de cada artículo y fija un límite personal anterior al máximo de la plataforma.`]},{heading:`Consolida pensando en compatibilidad`,paragraphs:[`Artículos con baterías, líquidos, imanes, alimentos, marcas u otras restricciones pueden limitar rutas. Los objetos pesados pueden aplastar textiles; lo frágil puede necesitar refuerzo o paquete separado.`]},{heading:`Compara consolidar y dividir con honestidad`,paragraphs:[`Una caja puede ahorrar cargos base, pero también activar peso volumétrico, umbrales de tamaño o incompatibilidades. Compara una cotización consolidada con dos cotizaciones reales, no con una alternativa imaginada.`]},{heading:`Compara rutas más allá del precio`,paragraphs:[`Revisa regla de peso, plazo estimado, seguimiento, compensación, restricciones y trato en destino. Los impuestos y las reglas de importación dependen del país y no son una promesa del directorio.`]},{heading:`Lee el seguimiento como una secuencia`,paragraphs:[`El tracking muestra escaneos, no movimiento continuo. Conserva número, ruta y fecha; un periodo sin actualización no prueba pérdida, pero una excepción debe revisarse con la parte adecuada.`]},{heading:`Ensaya la presentación final`,paragraphs:[`Antes de pagar revisa contenido, dirección, ruta, declaración, protección, embalaje y peso facturable. Si el total supera la estimación, busca la causa antes de cambiar de ruta o dividir.`]},{heading:`Un ritmo de planificación útil`,paragraphs:[`Compra pensando en coste total, inspecciona cada llegada, resuelve pronto, combina artículos compatibles, compara rutas elegibles y revisa el paquete final.`]}]},{visual:{eyebrow:`ESCALA DE PRUEBAS`,title:`Una reseña útil muestra el origen de cada afirmación.`,caption:`Las declaraciones de la plataforma explican el servicio previsto; un informe documenta un caso; la cuenta actual controla precios y plazos.`,items:[[`Servicio publicado`,`Compra por enlace, inspección, fotos y 90 días.`],[`Caso observado`,`Un comprador informó de una diferencia de talla detectada y una devolución gestionada.`],[`Aún desconocido`,`Coste final, resultado del paquete y consistencia entre pedidos.`],[`Tu verificación`,`Comprueba cotización, pruebas y recurso actual antes de pagar.`]]},sources:[[`Web pública de LoloBuy`,`Fuente primaria para compra, inspección, fotografía y almacenamiento.`],[`Informe preliminar independiente`,`Relato en primera persona sobre calzado, bolsos, QC, soporte y una diferencia de talla.`],[`Guía comunitaria de pedidos`,`Descripción pública usada para comparar el caso con el flujo anunciado.`]],intro:[`Los servicios jóvenes acumulan promoción antes que suficientes pedidos independientes completos. LoloBuy está en esa etapa: el modelo público es reconocible, pero la base de reseñas comprobables sigue siendo pequeña.`,`Este análisis estudia un informe preliminar y separa lo que realmente probó de las etapas aún sin completar. Esa trazabilidad es más útil que una puntuación.`],sections:[{heading:`Por qué importa la palabra «preliminar»`,paragraphs:[`El propio autor presentó su opinión antes de completar el ciclo internacional. Por tanto, el caso informa sobre compra, almacén y soporte, no sobre coste final, tránsito, aduanas o entrega.`]},{heading:`Qué probó realmente el comprador`,paragraphs:[`El informe describió compras de calzado y bolsos, navegación, fotos QC, soporte y una devolución por tallas distintas. Es evidencia concreta de un caso, no una muestra amplia.`]},{heading:`El incidente de dos tallas es el detalle más útil`,paragraphs:[`Detectar dos tallas diferentes demuestra por qué el QC debe empezar por identidad y variante. La devolución gestionada es una señal positiva para ese caso, no una garantía de todos los vendedores o plazos.`]},{heading:`Qué pueden y no pueden decir unas fotos «sólidas»`,paragraphs:[`La valoración sugiere que el comprador pudo tomar decisiones con las imágenes, pero no define número, ángulos o consistencia. Las fotos no prueban autenticidad, duración o composición.`]},{heading:`Los comentarios sobre interfaz e historial son útiles, pero personales`,paragraphs:[`Una interfaz comprensible y el historial de navegación reducen fricción para ese usuario. Otras personas, dispositivos o idiomas pueden vivir una experiencia distinta.`]},{heading:`Soporte rápido en un caso es una señal, no una promesa`,paragraphs:[`La respuesta descrita es positiva, pero una sola conversación no establece tiempos de servicio generales ni resultados para casos complejos.`]},{heading:`El enlace de referencia debe permanecer visible`,paragraphs:[`Si el autor recibe un beneficio por referidos, el incentivo debe considerarse al valorar el tono. No invalida hechos documentados, pero exige separar observación de recomendación.`]},{heading:`Las mayores incógnitas empiezan al enviar el paquete`,paragraphs:[`Sin paquete entregado no se pueden juzgar coste total, peso facturable, rutas, embalaje, seguimiento, aduanas o consistencia. Comparaciones como «más barato» o «más rápido» siguen sin probarse.`]},{heading:`Cómo hacer un primer pedido con pocas suposiciones`,paragraphs:[`Elige una opción clara y medible, guarda la ficha y variante, evalúa el QC antes de ampliar el pedido y espera los datos preparados antes de juzgar el transporte.`],bullets:[`Producto con opciones claras`,`Ficha y variante guardadas`,`QC antes de más pedidos`,`Datos del paquete antes del coste`,`Resultado entregado documentado`]},{heading:`Un veredicto prudente`,paragraphs:[`El informe es una señal temprana positiva para compra y almacén: detectó una diferencia y describe fotos y soporte útiles. No basta para una puntuación global; falta el ciclo internacional completo y una muestra mayor.`]}]}],de:[{visual:{eyebrow:`VIER-QUELLEN-REGEL`,title:`Eine Entscheidung, vier verschiedene Quellen.`,caption:`Das Verzeichnis startet die Suche; Live-Angebot, QC-Nachweis und Packdaten übernehmen später.`,items:[[`Verzeichnis`,`Produktidee finden und Kategorien vergleichen.`],[`Live-Angebot`,`Verkäufer, Option, Preis und Beschreibung bestätigen.`],[`Lager-QC`,`Den tatsächlich eingegangenen Artikel prüfen.`],[`Gepacktes Paket`,`Versand nach Gewicht, Maßen und Zulässigkeit wählen.`]]},sources:[[`Öffentliche LoloBuy-Website`,`Öffentliche Angaben zu Einkauf, Prüfung, Fotos und 90 Tagen Lagerung.`],[`LoloBuy Community-Bestellleitfaden`,`Öffentlicher Überblick über die Bestellphasen.`]],intro:[`Ein gutes Spreadsheet verkürzt den Weg von einer Idee zu einem prüfbaren Angebot. Es ersetzt nicht die Kontrolle von Verkäufer, Preis, Optionen und Einschränkungen.`,`Dieser Ratgeber trennt Verzeichnis, Live-Angebot, QC-Fotos und endgültige Paketentscheidung.`],sections:[{heading:`Mit Absicht statt Endlos-Feed beginnen`,paragraphs:[`Kategorie, Zweck, Material, Maße, Farben und Budget vor der Suche festlegen. Zwei oder drei Kandidaten vergleichen statt die erste Abbildung zu wählen.`],bullets:[`Artikeltyp und Zweck`,`Wichtige Maße`,`Artikel- und Gesamtkosten trennen`,`Mehrere Kandidaten`]},{heading:`Jeden Eintrag als Hinweis behandeln`,paragraphs:[`Der Verkäufer steuert Bilder, Bestand, Varianten, Preis und Text. Aktuelles Angebot öffnen, exakte Option wählen und Maße mit einem passenden eigenen Artikel vergleichen.`]},{heading:`Öffentlich bestätigte LoloBuy-Schritte erkennen`,paragraphs:[`Öffentlich beschrieben sind Bestellung per Link, Prüfung und Fotos nach Lagereingang sowie 90 Tage kostenlose Lagerung. Festpreise, Garantielaufzeiten und allgemeine Fotozahlen müssen im Live-Konto geprüft werden.`]},{heading:`Aus dem Link eine Bestellnotiz machen`,paragraphs:[`URL, Datum, Farbe, Größe, Menge, Originaltext der Option, Maßtabelle und Preis speichern. So bleiben mehrdeutige Übersetzungen und Varianten nachvollziehbar.`],bullets:[`URL und Datum`,`Exakte Option`,`Schlüsselmaße`,`Preis und China-Versand`,`Unverzichtbares Merkmal`]},{heading:`Beleglose Spreadsheet-Aussagen hinterfragen`,paragraphs:[`„Verifiziert“, „am günstigsten“ oder „täglich aktualisiert“ brauchen Nachweise. Ein Verzeichniseintrag beweist weder Zuverlässigkeit, Echtheit noch Endkosten.`]},{heading:`Verkäuferbilder von Lager-QC trennen`,paragraphs:[`Verkäuferbilder zeigen das Versprechen; QC-Fotos den eingegangenen Artikel. Erst Identität und Variante, dann Verarbeitung und Schäden prüfen.`]},{heading:`Einen Entscheidungspreis kalkulieren`,paragraphs:[`Produkt, China-Versand, Leistungen, internationaler Transport, Verpackung und Steuern getrennt planen. Die endgültige Entscheidung basiert auf dem gepackten Paket.`],bullets:[`China-Versand prüfen`,`Gewicht und Volumen schätzen`,`Verpackungspuffer`,`Endangebot prüfen`]},{heading:`Kurzen Prüfvermerk behalten`,paragraphs:[`Link, Option, Maßtabelle, Preis und Datum speichern. Lesezeichen garantieren keine Verfügbarkeit; vor der Bestellung erneut prüfen.`]},{heading:`Die praktische Regel`,paragraphs:[`Spreadsheet zum Entdecken, Live-Angebot zum Bestätigen, QC-Fotos zum Prüfen und Paketangebot zum Versenden nutzen.`]}]},{visual:{eyebrow:`QC-REIHENFOLGE`,title:`Nachweise in der richtigen Reihenfolge prüfen.`,caption:`Eine ruhige Reihenfolge verhindert, dass Kleinigkeiten eine falsche Größe, fehlende Teile oder Strukturprobleme überdecken.`,items:[[`Identität`,`Artikel, Farbe, Größe, Menge und Teile.`],[`Struktur`,`Form, Symmetrie, Ausrichtung und Schäden.`],[`Maße`,`Passformrelevante Werte mit Referenz.`],[`Aktion`,`Annehmen, gezielt prüfen lassen oder aktuellen Weg nutzen.`]]},sources:[[`Öffentliche LoloBuy-Website`,`Bestätigt Qualitätsprüfung und Fotografie nach Lagereingang.`],[`Früher unabhängiger Nutzerbericht`,`Ein vorläufiger Fall zu QC, Größenabweichung und Support; keine repräsentative Bewertung.`]],intro:[`QC-Fotos funktionieren am besten mit Checkliste. Gesamteindruck kann Probleme verbergen, Pixel-Zoom kann durch Licht oder Perspektive Fehlalarm auslösen.`,`Ziel ist eine fundierte Annahme-, Umtausch- oder Rückgabeentscheidung, nicht der Beweis perfekter Ware.`],sections:[{heading:`Mit der Auftragsidentität beginnen`,paragraphs:[`Artikel, Farbe, Modell, Größe, Menge und enthaltene Teile zuerst bestätigen. Verpackung nur erwarten, wenn sie Bestandteil des Angebots war.`],bullets:[`Artikel und Farbe`,`Größe oder Variante`,`Menge und Teile`,`Keine sichtbaren Schäden`]},{heading:`Grenze öffentlicher Angaben klar halten`,paragraphs:[`LoloBuy bestätigt Prüfung und Fotos, aber keine allgemeine kostenlose Bildzahl oder dauerhafte Zusatzpreise. Tatsächliche Bilder und Kontooptionen verwenden.`]},{heading:`Form und Symmetrie vor Kleinigkeiten lesen`,paragraphs:[`Bei Kleidung Schultern und Ärmel, bei Schuhen Paar und Sohlen, bei Taschen Silhouette und Griffe vergleichen. Perspektive durch mehrere Blickwinkel ausgleichen.`]},{heading:`Licht, Kompression und Abstand berücksichtigen`,paragraphs:[`Beleuchtung verschiebt Farben, Weitwinkel verzerrt Kanten und Kompression zerstört Textur. Dasselbe Merkmal in mehreren Bildern und mit festen Referenzen prüfen.`]},{heading:`Passformfragen mit Maßen beantworten`,paragraphs:[`Linealposition mit Maßtabelle und eigenem Artikel vergleichen. Kleine manuelle Abweichungen zulassen, fehlendes entscheidendes Maß gezielt anfragen.`]},{heading:`Eine Antwort statt einfach mehr Fotos verlangen`,paragraphs:[`Merkmal, Winkel und Referenz nennen: Innenlänge, Paaransicht, Brustweite oder Schadensdetail. Nur Nachweise priorisieren, die die Entscheidung ändern.`],bullets:[`Merkmal nennen`,`Winkel angeben`,`Abweichung beschreiben`,`Entscheidungsrelevanten Nachweis wählen`]},{heading:`Kleidungs-Checkliste`,paragraphs:[`Ausschnitt, Verschluss, Knöpfe, Druck, Taschen, Nähte, Flecken und Löcher prüfen; bei Hosen Bund, Leibhöhe, Beinform und Saum.`]},{heading:`Schuhe, Taschen und Zubehör`,paragraphs:[`Bei Schuhen Paar, Sohlen, Kleber und Paneele vergleichen. Bei Taschen Form, Ecken, Griffe, Gurte, Reißverschluss, Futter und Beschläge ansehen.`]},{heading:`Wissen, was Fotos nicht belegen`,paragraphs:[`Bilder beweisen weder Haltbarkeit, Zusammensetzung, Komfort, Elektronikfunktion noch Echtheit und zeigen nicht alle inneren Teile.`]},{heading:`Nachweise vor dem Weiterversand sichern`,paragraphs:[`Referenz, Angebot, Option und wichtige Bilder speichern. Datum, Bild und gewünschte Lösung notieren, ohne Fristen zu verpassen.`]},{heading:`Ruhige Annahme- oder Handlungsentscheidung`,paragraphs:[`Befund als normale Variation, akzeptablen Schönheitsfehler oder wesentliche Abweichung einordnen; dann aktuelle Frist und Abhilfe prüfen.`]}]},{visual:{eyebrow:`GESAMTKOSTEN-STAPEL`,title:`Der Produktpreis ist nur die erste Zeile.`,caption:`Schätzungen und bestätigte Gebühren trennen. Sinnvoll wird die internationale Wahl erst mit Packdaten.`,items:[[`Produkt`,`Gewählte Variante zum aktuellen Preis.`],[`China-Kosten`,`Inlandsversand und klar ausgewiesene Gebühren.`],[`Paket`,`Verpackung, Gewicht, Maße und Routenregeln.`],[`Ziel`,`Internationaler Transport plus Steuern und Zoll.`]]},sources:[[`Öffentliche LoloBuy-Website`,`90 Tage kostenlose Lagerung und Lagerleistungen.`],[`Community-Bestellleitfaden`,`Bündelung, Routenwahl, internationale Zahlung und Tracking.`]],intro:[`Mehrere Artikel zusammen sind nicht automatisch günstiger. Bündelung kann Grundgebühren sparen, doch Volumen, Einschränkungen und Zeit bleiben wichtig.`,`Die beworbenen 90 Tage sind ein Planungsfenster, kein Anlass, bis zum letzten Tag zu warten.`],sections:[{heading:`Mit veröffentlichten LoloBuy-Angaben starten`,paragraphs:[`Öffentliche Quellen stützen Einkaufshilfe, Prüfung, Fotos, 90 Tage Lagerung und spätere Bündelung. Sie liefern keine dauerhafte Paketpreisliste.`]},{heading:`Paket zuerst auf Papier bauen`,paragraphs:[`Gewicht, Maße, Material und Schutzbedarf je Artikel notieren. Problematische Mischungen und eine persönliche Versandentscheidung vorab erkennen.`]},{heading:`Schätzungen als Spannen führen`,paragraphs:[`Verkäufergewicht ist nicht Packgewicht. Niedrig- und Hochwert plus Zeitpuffer für Versand, Eingang, QC, Packen, Export und Zoll verwenden.`],bullets:[`Gewichtsspanne`,`Wahrscheinliche Verpackung`,`Kompatibilität`,`Eigener Versandtermin`]},{heading:`Ist- und Volumengewicht verstehen`,paragraphs:[`Istgewicht kommt von der Waage, Volumengewicht aus Außenmaßen und Routenformel. Berechnet werden kann der höhere Wert; weniger Verpackung kann Schutz kosten.`],bullets:[`Dicht: oft Istgewicht`,`Leicht und groß: oft Volumen`,`Verpackung ändert beides`,`Lagerdaten schlagen Schätzung`]},{heading:`Lagerung als Puffer nutzen`,paragraphs:[`Ankünfte können warten und QC-Probleme geklärt werden. Datum je Artikel notieren und eine frühere persönliche Frist setzen.`]},{heading:`Mit Kompatibilität konsolidieren`,paragraphs:[`Batterien, Flüssigkeiten, Magnete und andere Kategorien können Routen einschränken. Schweres kann Textilien drücken; Zerbrechliches braucht Schutz oder Trennung.`]},{heading:`Bündeln und Teilen ehrlich vergleichen`,paragraphs:[`Eine Box kann Grundgebühren sparen, aber Volumengewicht oder Größenlimits auslösen. Ein bestätigtes Bündelangebot mit zwei bestätigten Teilangeboten vergleichen.`]},{heading:`Routen nicht nur nach Preis vergleichen`,paragraphs:[`Gewichtsregel, Laufzeit, Tracking, Entschädigung, Einschränkungen und Zielland prüfen. Steuern und Einfuhrrecht sind keine Verzeichnisgarantie.`]},{heading:`Tracking als Scanfolge lesen`,paragraphs:[`Tracking zeigt Ereignisse, nicht dauernde Bewegung. Nummer, Route und Datum speichern; längere Ruhe anhand aktueller Routenhife oder Ausnahme prüfen.`]},{heading:`Endeinreichung durchspielen`,paragraphs:[`Inhalt, Adresse, Route, Deklaration, Schutz, Verpackung und Abrechnungsgewicht vor Zahlung prüfen. Große Abweichungen zuerst erklären.`]},{heading:`Ein nützlicher Planungsrhythmus`,paragraphs:[`Gesamtkosten mitdenken, Ankünfte prüfen, Probleme früh lösen, kompatibel bündeln, zulässige Routen vergleichen und Endpaket prüfen.`]}]},{visual:{eyebrow:`BELEGLEITER`,title:`Ein nützlicher Bericht zeigt die Quelle jeder Aussage.`,caption:`Plattformaussagen beschreiben den Sollprozess, ein Bericht einen Fall, das Konto aktuelle Preise und Fristen.`,items:[[`Veröffentlichter Service`,`Linkkauf, Prüfung, Fotos und 90 Tage.`],[`Beobachteter Fall`,`Größenabweichung entdeckt und Rückgabe bearbeitet.`],[`Noch offen`,`Endkosten, Paketergebnis und Wiederholbarkeit.`],[`Eigene Prüfung`,`Angebot, Belege und Abhilfe vor Zahlung prüfen.`]]},sources:[[`Öffentliche LoloBuy-Website`,`Primärquelle zu Einkauf, Prüfung, Fotos und Lagerung.`],[`Vorläufiger unabhängiger Bericht`,`Erfahrung mit Schuhen, Taschen, QC, Support und Größenabweichung.`],[`Community-Bestellleitfaden`,`Öffentliche Prozessbeschreibung zum Vergleich.`]],intro:[`Junge Dienste sammeln Werbung früher als vollständige unabhängige Bestellnachweise. Bei LoloBuy ist das Modell sichtbar, die überprüfbare Berichtsbasis aber noch klein.`,`Diese Analyse trennt getestete Einkauf- und Lagerphasen von noch nicht abgeschlossenen Versandphasen.`],sections:[{heading:`Warum „vorläufig“ wichtig ist`,paragraphs:[`Der Autor berichtete vor Abschluss des internationalen Zyklus. Der Fall sagt etwas über Einkauf, Lager und Support, nicht über Endkosten, Zoll oder Zustellung.`]},{heading:`Was der Käufer tatsächlich testete`,paragraphs:[`Beschrieben wurden Schuhe, Taschen, Navigation, QC-Fotos, Support und Rückgabe wegen zweier Größen. Konkreter Fall, keine breite Stichprobe.`]},{heading:`Der Zwei-Größen-Fall ist das nützlichste Detail`,paragraphs:[`Er zeigt, warum QC mit Identität und Variante beginnt. Die bearbeitete Rückgabe ist positiv für diesen Fall, keine allgemeine Garantie.`]},{heading:`Was „solide QC-Fotos“ sagen können`,paragraphs:[`Die Bilder waren für die Entscheidung offenbar brauchbar, ohne Umfang oder Konsistenz zu belegen. Echtheit, Haltbarkeit und Material bleiben offen.`]},{heading:`Oberfläche und Verlauf sind nützlich, aber persönlich`,paragraphs:[`Verständliche Bedienung und Verlauf halfen diesem Nutzer. Andere Geräte, Sprachen oder Erwartungen können abweichen.`]},{heading:`Schneller Support in einem Fall ist kein Serviceversprechen`,paragraphs:[`Die Antwort ist ein positives Signal, reicht aber nicht für allgemeine Reaktionszeiten oder komplexe Fälle.`]},{heading:`Ein Empfehlungslink muss sichtbar bleiben`,paragraphs:[`Ein möglicher Vorteil beeinflusst die Tonbewertung. Dokumentierte Fakten bleiben nutzbar, Beobachtung und Empfehlung müssen getrennt werden.`]},{heading:`Die größten Fragen beginnen beim Paketversand`,paragraphs:[`Ohne zugestelltes Paket bleiben Gesamtkosten, Routen, Verpackung, Tracking, Zoll und Beständigkeit unbewertet.`]},{heading:`Einen ersten Auftrag mit wenigen Annahmen durchführen`,paragraphs:[`Klare, messbare Option wählen, Angebot sichern, QC vor weiteren Bestellungen bewerten und Packdaten vor der Versandbewertung abwarten.`],bullets:[`Klare Optionen`,`Angebot und Variante sichern`,`QC zuerst`,`Packdaten abwarten`,`Zustellergebnis dokumentieren`]},{heading:`Ein vorsichtiges Urteil`,paragraphs:[`Der Bericht ist ein frühes positives Signal für Einkauf und Lager, aber keine Gesamtbewertung. Internationaler Zyklus und größere Stichprobe fehlen.`]}]}],fr:[{visual:{eyebrow:`RÈGLE DES QUATRE SOURCES`,title:`Une décision, quatre sources différentes.`,caption:`Le catalogue lance la recherche ; la fiche actuelle, le QC et le colis emballé prennent le relais.`,items:[[`Catalogue`,`Trouver une idée et comparer les catégories.`],[`Fiche actuelle`,`Confirmer vendeur, option, prix et description.`],[`QC d'entrepôt`,`Inspecter l'article réellement reçu.`],[`Colis emballé`,`Choisir selon poids, dimensions et admissibilité.`]]},sources:[[`Site public LoloBuy`,`Déclarations sur achat, inspection, photos et 90 jours de stockage.`],[`Guide communautaire LoloBuy`,`Aperçu public des étapes de commande.`]],intro:[`Un spreadsheet utile réduit le trajet entre une idée et une fiche évaluable. Il ne remplace pas la vérification du vendeur, du prix, des options et des restrictions.`,`Ce guide sépare catalogue, fiche actuelle, preuves QC et décision finale d'expédition.`],sections:[{heading:`Commencer par l'intention, pas par un flux infini`,paragraphs:[`Définissez catégorie, usage, matière, mesures, couleurs et budget avant d'ouvrir de nombreux liens. Comparez deux ou trois candidats.`],bullets:[`Type et usage`,`Mesures nécessaires`,`Prix article et coût total séparés`,`Plusieurs candidats`]},{heading:`Traiter chaque entrée comme une piste`,paragraphs:[`Le vendeur contrôle images, stock, variantes, prix et texte. Ouvrez la fiche actuelle, sélectionnez l'option exacte et comparez les mesures.`]},{heading:`Connaître les étapes confirmées par LoloBuy`,paragraphs:[`La page publique décrit commande par lien, inspection, photos et 90 jours de stockage. Tarifs permanents, délais garantis et nombre universel de photos restent à vérifier dans le compte.`]},{heading:`Transformer le lien en note de commande`,paragraphs:[`Conservez URL, date, couleur, taille, quantité, texte original de l'option, tableau et prix. Une note précise réduit l'ambiguïté.`],bullets:[`URL et date`,`Option exacte`,`Mesures clés`,`Prix et livraison chinoise`,`Détail indispensable`]},{heading:`Se méfier des affirmations sans preuve`,paragraphs:[`« Vérifié », « moins cher » ou « mis à jour chaque jour » exigent des preuves. Une présence au catalogue ne prouve ni fiabilité, ni authenticité, ni coût final.`]},{heading:`Séparer photos vendeur et photos QC`,paragraphs:[`Les premières présentent l'offre ; les secondes documentent l'article reçu. Vérifiez identité et variante avant construction et dommages.`]},{heading:`Calculer un prix de décision`,paragraphs:[`Additionnez produit, livraison chinoise, services, transport international, emballage et taxes. Estimez pour planifier, utilisez le colis réel pour décider.`],bullets:[`Livraison chinoise`,`Poids et volume`,`Marge d'emballage`,`Devis final`]},{heading:`Garder une trace courte`,paragraphs:[`Conservez lien, option, tableau, prix et date. Un favori ne garantit pas la disponibilité ; revérifiez avant commande.`]},{heading:`La règle pratique`,paragraphs:[`Catalogue pour découvrir, fiche pour confirmer, QC pour inspecter et devis final pour expédier.`]}]},{visual:{eyebrow:`ORDRE DU QC`,title:`Examiner les preuves dans le bon ordre.`,caption:`Une séquence calme empêche un détail mineur de masquer mauvaise taille, pièce absente ou problème structurel.`,items:[[`Identité`,`Article, couleur, taille, quantité et pièces.`],[`Structure`,`Forme, symétrie, alignement et dommages.`],[`Mesures`,`Dimensions critiques comparées à une référence.`],[`Action`,`Accepter, demander un contrôle ciblé ou utiliser le recours actuel.`]]},sources:[[`Site public LoloBuy`,`Confirme contrôle qualité et photographies après réception.`],[`Premier témoignage indépendant`,`Cas préliminaire sur QC, écart de taille et support ; pas une note représentative.`]],intro:[`Les photos QC sont plus utiles avec une liste. Une impression générale cache des problèmes ; zoomer chaque pixel crée parfois de fausses alertes.`,`Le but est de décider en connaissance de cause, pas de prouver la perfection.`],sections:[{heading:`Commencer par l'identité de la commande`,paragraphs:[`Confirmez article, couleur, modèle, taille, quantité et pièces avant les coutures. N'attendez l'emballage que s'il faisait partie de l'offre.`],bullets:[`Article et couleur`,`Taille ou variante`,`Quantité et pièces`,`Aucun dommage évident`]},{heading:`Garder claire la limite des faits publics`,paragraphs:[`LoloBuy confirme inspection et photos, mais pas un nombre universel gratuit ni un tarif permanent pour des images supplémentaires. Utilisez les éléments réels du compte.`]},{heading:`Lire forme et symétrie avant les petits détails`,paragraphs:[`Comparez épaules et manches, paire de chaussures et semelles, silhouette et poignées. Plusieurs angles réduisent l'effet de perspective.`]},{heading:`Tenir compte de la lumière et de la compression`,paragraphs:[`Éclairage, grand-angle et compression modifient couleur, bords et texture. Comparez plusieurs cadres avec règle ou étiquette comme référence.`]},{heading:`Utiliser les mesures pour la coupe`,paragraphs:[`Comparez la règle au tableau vendeur et à un article adapté. Acceptez de faibles écarts manuels, demandez la mesure décisive manquante.`]},{heading:`Demander une réponse, pas seulement plus de photos`,paragraphs:[`Nommez détail, angle et référence : semelle intérieure, vue de la paire, largeur poitrine ou dommage. Privilégiez les preuves qui changent la décision.`],bullets:[`Nommer le détail`,`Indiquer l'angle`,`Décrire l'écart`,`Choisir une preuve décisive`]},{heading:`Liste vêtements`,paragraphs:[`Contrôlez col, zip, boutons, motif, poches, coutures, taches et trous ; pour un pantalon, taille, fourche, jambe et ourlet.`]},{heading:`Chaussures, sacs et accessoires`,paragraphs:[`Pour les chaussures comparez paire, semelles, colle et panneaux. Pour les sacs vérifiez forme, coins, poignées, sangles, zip, doublure et métal.`]},{heading:`Savoir ce que les photos ne prouvent pas`,paragraphs:[`Elles ne prouvent ni durabilité, composition, confort, électronique ou authenticité et ne montrent pas toutes les parties internes.`]},{heading:`Sauvegarder les preuves avant l'expédition`,paragraphs:[`Conservez référence, fiche, option et images importantes. Notez date, photo et solution demandée sans dépasser le délai.`]},{heading:`Décider calmement d'accepter ou d'agir`,paragraphs:[`Classez variation normale, défaut cosmétique acceptable ou écart important, puis vérifiez délai et recours actuels.`]}]},{visual:{eyebrow:`PILE DU COÛT FINAL`,title:`Le prix produit n'est que la première ligne.`,caption:`Séparez estimations et frais confirmés. Le choix international devient réel avec les données du colis.`,items:[[`Produit`,`Variante choisie au prix actuel.`],[`Coût en Chine`,`Livraison locale et frais affichés.`],[`Colis`,`Emballage, poids, dimensions et règles.`],[`Destination`,`Fret international, taxes et douane.`]]},sources:[[`Site public LoloBuy`,`90 jours de stockage gratuit et services d'entrepôt.`],[`Guide communautaire`,`Consolidation, route, paiement international et suivi.`]],intro:[`Regrouper plusieurs articles ne garantit pas un coût inférieur. La consolidation peut économiser des frais de base, mais volume, restrictions et calendrier comptent.`,`Les 90 jours annoncés sont une marge de planification, pas une invitation à attendre le dernier jour.`],sections:[{heading:`Partir de ce que LoloBuy publie`,paragraphs:[`Les sources publiques soutiennent achat assisté, inspection, photos, stockage et consolidation ultérieure. Elles ne créent pas de tarif permanent pour votre colis.`]},{heading:`Construire d'abord le colis sur papier`,paragraphs:[`Listez poids, dimensions, matière et protection. Repérez les mélanges difficiles et décidez ce qui peut attendre.`]},{heading:`Garder les estimations en fourchettes`,paragraphs:[`Le poids vendeur n'est pas le poids emballé. Utilisez valeurs basse et haute plus une marge pour chaque étape logistique.`],bullets:[`Fourchette de poids`,`Emballage probable`,`Compatibilité`,`Date personnelle d'envoi`]},{heading:`Comprendre poids réel et volumétrique`,paragraphs:[`Le réel vient de la balance ; le volumétrique des dimensions et d'une formule de route. Le plus élevé peut être facturé ; retirer une boîte réduit parfois la protection.`],bullets:[`Dense : souvent poids réel`,`Léger et grand : volume`,`L'emballage change les deux`,`Les données d'entrepôt priment`]},{heading:`Utiliser le stockage comme marge`,paragraphs:[`Il permet d'attendre les arrivées et de résoudre le QC. Notez la date de chaque article et fixez une échéance antérieure.`]},{heading:`Consolider selon la compatibilité`,paragraphs:[`Batteries, liquides, aimants et autres catégories peuvent limiter les routes. Les objets lourds écrasent les textiles ; le fragile exige protection ou séparation.`]},{heading:`Comparer honnêtement consolidation et séparation`,paragraphs:[`Une boîte économise parfois les frais de base mais peut déclencher volume ou limites. Comparez un devis regroupé à deux devis réels.`]},{heading:`Comparer les routes au-delà du prix`,paragraphs:[`Vérifiez règle de poids, délai, suivi, indemnisation, restrictions et destination. Taxes et importation relèvent du pays.`]},{heading:`Lire le suivi comme une suite de scans`,paragraphs:[`Le suivi montre des événements, pas le mouvement continu. Gardez numéro, route et date et traitez les exceptions avec la partie compétente.`]},{heading:`Répéter la soumission finale`,paragraphs:[`Avant paiement, contrôlez contenu, adresse, route, déclaration, protection, emballage et poids facturable. Expliquez tout écart important.`]},{heading:`Un rythme de planification utile`,paragraphs:[`Penser au coût total, inspecter, résoudre tôt, regrouper ce qui est compatible, comparer les routes et relire le colis final.`]}]},{visual:{eyebrow:`ÉCHELLE DES PREUVES`,title:`Un avis utile montre la source de chaque affirmation.`,caption:`La plateforme décrit le service prévu, un témoignage documente un cas et le compte actuel contrôle prix et délais.`,items:[[`Service publié`,`Achat par lien, inspection, photos et 90 jours.`],[`Cas observé`,`Écart de taille détecté et retour traité.`],[`Encore inconnu`,`Coût final, résultat du colis et régularité.`],[`Votre contrôle`,`Vérifier devis, preuves et recours avant paiement.`]]},sources:[[`Site public LoloBuy`,`Source primaire pour achat, inspection, photos et stockage.`],[`Témoignage préliminaire indépendant`,`Chaussures, sacs, QC, support et écart de taille.`],[`Guide communautaire`,`Processus public utilisé pour comparer le cas.`]],intro:[`Les jeunes services accumulent la promotion avant les commandes indépendantes complètes. LoloBuy présente un modèle clair, mais peu de témoignages vérifiables.`,`Cette analyse distingue les étapes réellement testées de celles qui restent inachevées.`],sections:[{heading:`Pourquoi le mot « préliminaire » compte`,paragraphs:[`L'auteur écrivait avant la fin du cycle international. Le cas informe sur achat, entrepôt et support, pas sur coût final, douane ou livraison.`]},{heading:`Ce que l'acheteur a réellement testé`,paragraphs:[`Le récit couvre chaussures, sacs, navigation, QC, support et retour lié à deux tailles. C'est un cas concret, pas un large échantillon.`]},{heading:`L'incident des deux tailles est le détail le plus utile`,paragraphs:[`Il montre pourquoi le QC commence par identité et variante. Le retour traité est positif pour ce cas, sans garantir tous les vendeurs.`]},{heading:`Ce que des photos « solides » peuvent dire`,paragraphs:[`Les images ont apparemment permis une décision sans prouver leur nombre ou constance. Authenticité, durée et matière restent inconnues.`]},{heading:`Interface et historique : utiles mais personnels`,paragraphs:[`Une interface claire et l'historique ont aidé cet utilisateur. Appareils, langues et attentes peuvent produire une autre expérience.`]},{heading:`Un support réactif dans un cas n'est pas une promesse`,paragraphs:[`La réponse est un signal positif, insuffisant pour établir des délais généraux ou des résultats complexes.`]},{heading:`Le lien de parrainage doit rester visible`,paragraphs:[`Un avantage potentiel influence l'évaluation du ton. Les faits documentés restent utiles si observation et recommandation sont séparées.`]},{heading:`Les plus grandes questions commencent à l'envoi`,paragraphs:[`Sans colis livré, coût, routes, emballage, suivi, douane et régularité ne peuvent être jugés.`]},{heading:`Faire une première commande avec peu d'hypothèses`,paragraphs:[`Choisissez une option claire, sauvegardez la fiche, évaluez le QC avant d'ajouter et attendez les données emballées avant de juger le fret.`],bullets:[`Options claires`,`Fiche et variante sauvegardées`,`QC d'abord`,`Données du colis`,`Résultat livré documenté`]},{heading:`Un verdict prudent`,paragraphs:[`Le récit est un signal précoce positif pour achat et entrepôt, pas une note globale. Le cycle international et un échantillon plus large manquent.`]}]}],it:[{visual:{eyebrow:`REGOLA DELLE QUATTRO FONTI`,title:`Una decisione, quattro fonti diverse.`,caption:`Il catalogo avvia la ricerca; scheda attuale, QC e pacco preparato controllano le fasi successive.`,items:[[`Catalogo`,`Trova un'idea e confronta categorie.`],[`Scheda attuale`,`Conferma venditore, opzione, prezzo e descrizione.`],[`QC di magazzino`,`Controlla l'articolo realmente arrivato.`],[`Pacco preparato`,`Scegli in base a peso, dimensioni e idoneità.`]]},sources:[[`Sito pubblico LoloBuy`,`Dichiarazioni su acquisto, ispezione, foto e 90 giorni di deposito.`],[`Guida community LoloBuy`,`Panoramica pubblica delle fasi dell'ordine.`]],intro:[`Uno spreadsheet utile accorcia il percorso da un'idea a una scheda valutabile. Non sostituisce controllo di venditore, prezzo, opzioni e restrizioni.`,`Questa guida separa catalogo, scheda attuale, prove QC e decisione finale sul pacco.`],sections:[{heading:`Parti dall'intento, non da un feed infinito`,paragraphs:[`Definisci categoria, uso, materiale, misure, colori e budget prima di aprire molti link. Confronta due o tre candidati.`],bullets:[`Tipo e uso`,`Misure necessarie`,`Prezzo articolo e costo totale separati`,`Più candidati`]},{heading:`Tratta ogni voce come una pista`,paragraphs:[`Il venditore controlla immagini, stock, varianti, prezzo e testo. Apri la scheda attuale, scegli l'opzione esatta e confronta le misure.`]},{heading:`Conosci ciò che LoloBuy conferma pubblicamente`,paragraphs:[`La pagina descrive ordine tramite link, ispezione, foto e 90 giorni di deposito. Tariffe permanenti, tempi garantiti e quantità universali vanno verificati nell'account.`]},{heading:`Trasforma il link in una nota d'ordine`,paragraphs:[`Salva URL, data, colore, taglia, quantità, testo originale, tabella e prezzo. Una nota precisa riduce ambiguità.`],bullets:[`URL e data`,`Opzione esatta`,`Misure chiave`,`Prezzo e consegna cinese`,`Dettaglio indispensabile`]},{heading:`Diffida delle affermazioni senza prove`,paragraphs:[`“Verificato”, “più economico” o “aggiornato ogni giorno” richiedono prove. La presenza nel catalogo non dimostra affidabilità, autenticità o costo finale.`]},{heading:`Separa foto venditore e foto QC`,paragraphs:[`Le prime presentano l'offerta; le seconde documentano l'articolo ricevuto. Controlla identità e variante prima di costruzione e danni.`]},{heading:`Calcola un prezzo decisionale`,paragraphs:[`Considera prodotto, consegna cinese, servizi, trasporto internazionale, imballaggio e tasse. Stima per pianificare, usa il pacco reale per decidere.`],bullets:[`Consegna cinese`,`Peso e volume`,`Margine imballaggio`,`Preventivo finale`]},{heading:`Conserva un registro breve`,paragraphs:[`Salva link, opzione, tabella, prezzo e data. Un preferito non garantisce disponibilità; ricontrolla prima dell'ordine.`]},{heading:`La regola pratica`,paragraphs:[`Catalogo per scoprire, scheda per confermare, QC per ispezionare e preventivo finale per spedire.`]}]},{visual:{eyebrow:`ORDINE DEL QC`,title:`Esamina le prove nell'ordine giusto.`,caption:`Una sequenza calma evita che un dettaglio minore nasconda taglia errata, pezzo mancante o problema strutturale.`,items:[[`Identità`,`Articolo, colore, taglia, quantità e pezzi.`],[`Struttura`,`Forma, simmetria, allineamento e danni.`],[`Misure`,`Dimensioni critiche confrontate con un riferimento.`],[`Azione`,`Accetta, chiedi un controllo mirato o usa il rimedio attuale.`]]},sources:[[`Sito pubblico LoloBuy`,`Conferma controllo qualità e foto dopo l'arrivo.`],[`Prima esperienza indipendente`,`Caso preliminare su QC, differenza di taglia e supporto; non un punteggio rappresentativo.`]],intro:[`Le foto QC funzionano meglio con una lista. L'impressione generale nasconde problemi; lo zoom estremo crea falsi allarmi.`,`Lo scopo è decidere con informazioni, non provare la perfezione.`],sections:[{heading:`Inizia dall'identità dell'ordine`,paragraphs:[`Conferma articolo, colore, modello, taglia, quantità e pezzi prima delle cuciture. Aspettati l'imballaggio solo se incluso nell'offerta.`],bullets:[`Articolo e colore`,`Taglia o variante`,`Quantità e pezzi`,`Nessun danno evidente`]},{heading:`Mantieni chiaro il limite dei fatti pubblici`,paragraphs:[`LoloBuy conferma ispezione e foto, ma non una quantità universale gratuita o prezzi permanenti per extra. Usa immagini e opzioni reali dell'account.`]},{heading:`Leggi forma e simmetria prima dei dettagli`,paragraphs:[`Confronta spalle e maniche, coppia e suole, forma e manici. Più angoli riducono l'effetto della prospettiva.`]},{heading:`Considera luce, compressione e distanza`,paragraphs:[`Illuminazione, grandangolo e compressione cambiano colore, bordi e texture. Confronta più fotogrammi con righello o etichetta.`]},{heading:`Usa le misure per la vestibilità`,paragraphs:[`Confronta il righello con tabella venditore e un capo adatto. Accetta piccoli scarti manuali, chiedi la misura decisiva mancante.`]},{heading:`Chiedi una risposta, non solo più foto`,paragraphs:[`Indica dettaglio, angolo e riferimento: soletta, vista coppia, larghezza torace o danno. Dai priorità alle prove che cambiano la decisione.`],bullets:[`Nomina il dettaglio`,`Indica l'angolo`,`Descrivi la differenza`,`Scegli una prova decisiva`]},{heading:`Lista per abbigliamento`,paragraphs:[`Controlla collo, zip, bottoni, stampa, tasche, cuciture, macchie e fori; nei pantaloni vita, cavallo, gamba e orlo.`]},{heading:`Scarpe, borse e accessori`,paragraphs:[`Per le scarpe confronta coppia, suole, colla e pannelli. Per le borse forma, angoli, manici, cinturini, zip, fodera e metallo.`]},{heading:`Conosci ciò che le foto non provano`,paragraphs:[`Non provano durata, composizione, comfort, elettronica o autenticità e non mostrano tutte le parti interne.`]},{heading:`Salva le prove prima della spedizione`,paragraphs:[`Conserva riferimento, scheda, opzione e immagini importanti. Annota data, foto e soluzione senza perdere la scadenza.`]},{heading:`Decidi con calma se accettare o agire`,paragraphs:[`Classifica variazione normale, difetto estetico accettabile o differenza sostanziale, poi verifica scadenza e rimedio attuali.`]}]},{visual:{eyebrow:`STRATI DEL COSTO FINALE`,title:`Il prezzo prodotto è solo la prima riga.`,caption:`Separa stime e costi confermati. La scelta internazionale diventa reale con i dati del pacco.`,items:[[`Prodotto`,`Variante scelta al prezzo attuale.`],[`Costo in Cina`,`Consegna nazionale e addebiti mostrati.`],[`Pacco`,`Imballaggio, peso, dimensioni e regole.`],[`Destinazione`,`Trasporto internazionale, tasse e dogana.`]]},sources:[[`Sito pubblico LoloBuy`,`90 giorni di deposito gratuito e servizi di magazzino.`],[`Guida community`,`Consolidamento, rotta, pagamento internazionale e tracking.`]],intro:[`Raggruppare più articoli non garantisce un costo minore. Il consolidamento può ridurre spese base, ma volume, restrizioni e tempi contano.`,`I 90 giorni pubblicizzati sono una finestra di pianificazione, non un invito ad aspettare l'ultimo giorno.`],sections:[{heading:`Parti da ciò che LoloBuy pubblica`,paragraphs:[`Le fonti pubbliche supportano acquisto assistito, ispezione, foto, deposito e successivo consolidamento. Non creano un listino permanente per il tuo pacco.`]},{heading:`Costruisci prima il pacco su carta`,paragraphs:[`Elenca peso, dimensioni, materiale e protezione. Individua combinazioni difficili e decidi cosa può aspettare.`]},{heading:`Mantieni le stime in intervalli`,paragraphs:[`Il peso del venditore non è quello imballato. Usa valore basso e alto più margine per ogni fase logistica.`],bullets:[`Intervallo di peso`,`Imballaggio probabile`,`Compatibilità`,`Data personale di spedizione`]},{heading:`Comprendi peso reale e volumetrico`,paragraphs:[`Il reale viene dalla bilancia; il volumetrico da dimensioni e formula della rotta. Può essere addebitato il maggiore; togliere scatole riduce anche protezione.`],bullets:[`Denso: spesso peso reale`,`Leggero e grande: volume`,`Imballaggio cambia entrambi`,`Dati di magazzino migliori`]},{heading:`Usa il deposito come margine`,paragraphs:[`Permette di attendere arrivi e risolvere il QC. Registra la data di ogni articolo e fissa una scadenza precedente.`]},{heading:`Consolida in base alla compatibilità`,paragraphs:[`Batterie, liquidi, magneti e altre categorie possono limitare rotte. Gli oggetti pesanti schiacciano tessili; i fragili richiedono protezione o separazione.`]},{heading:`Confronta onestamente consolidamento e divisione`,paragraphs:[`Una scatola può risparmiare costi base ma attivare volume o limiti. Confronta un preventivo unito con due preventivi reali.`]},{heading:`Confronta le rotte oltre il prezzo`,paragraphs:[`Verifica regola di peso, tempi, tracking, compensazione, restrizioni e destinazione. Tasse e importazione dipendono dal paese.`]},{heading:`Leggi il tracking come sequenza di scansioni`,paragraphs:[`Il tracking mostra eventi, non movimento continuo. Conserva numero, rotta e data e gestisci le eccezioni con la parte corretta.`]},{heading:`Ripassa l'invio finale`,paragraphs:[`Prima di pagare controlla contenuto, indirizzo, rotta, dichiarazione, protezione, imballaggio e peso fatturabile. Spiega gli scarti importanti.`]},{heading:`Un ritmo utile di pianificazione`,paragraphs:[`Pensa al costo totale, ispeziona, risolvi presto, raggruppa ciò che è compatibile, confronta rotte e rileggi il pacco finale.`]}]},{visual:{eyebrow:`SCALA DELLE PROVE`,title:`Una recensione utile mostra la fonte di ogni affermazione.`,caption:`La piattaforma descrive il servizio previsto, un resoconto documenta un caso e l'account controlla prezzi e scadenze.`,items:[[`Servizio pubblicato`,`Acquisto tramite link, ispezione, foto e 90 giorni.`],[`Caso osservato`,`Differenza di taglia individuata e reso gestito.`],[`Ancora ignoto`,`Costo finale, risultato del pacco e coerenza.`],[`Tua verifica`,`Controlla preventivo, prove e rimedio prima di pagare.`]]},sources:[[`Sito pubblico LoloBuy`,`Fonte primaria per acquisto, ispezione, foto e deposito.`],[`Resoconto preliminare indipendente`,`Scarpe, borse, QC, supporto e differenza di taglia.`],[`Guida community`,`Processo pubblico usato per confrontare il caso.`]],intro:[`I servizi giovani raccolgono promozione prima di ordini indipendenti completi. LoloBuy mostra un modello chiaro, ma pochi resoconti verificabili.`,`Questa analisi separa le fasi realmente testate da quelle ancora incomplete.`],sections:[{heading:`Perché la parola «preliminare» conta`,paragraphs:[`L'autore scriveva prima della fine del ciclo internazionale. Il caso informa su acquisto, magazzino e supporto, non su costo finale, dogana o consegna.`]},{heading:`Cosa ha realmente testato l'acquirente`,paragraphs:[`Il resoconto copre scarpe, borse, navigazione, QC, supporto e reso per due taglie. È un caso concreto, non un campione ampio.`]},{heading:`L'incidente delle due taglie è il dettaglio più utile`,paragraphs:[`Mostra perché il QC parte da identità e variante. Il reso gestito è positivo per quel caso, non una garanzia generale.`]},{heading:`Cosa possono dire foto QC «solide»`,paragraphs:[`Le immagini sembrano aver consentito una decisione senza provarne numero o coerenza. Autenticità, durata e materiale restano ignoti.`]},{heading:`Interfaccia e cronologia sono utili, ma personali`,paragraphs:[`Interfaccia chiara e cronologia hanno aiutato quell'utente. Dispositivi, lingue e aspettative possono produrre esperienze diverse.`]},{heading:`Supporto rapido in un caso non è una promessa`,paragraphs:[`La risposta è un segnale positivo, insufficiente per stabilire tempi generali o risultati complessi.`]},{heading:`Il link referral deve restare visibile`,paragraphs:[`Un possibile vantaggio influenza il tono. I fatti documentati restano utili se osservazione e raccomandazione sono separate.`]},{heading:`Le domande maggiori iniziano con la spedizione`,paragraphs:[`Senza pacco consegnato non si giudicano costo, rotte, imballaggio, tracking, dogana o coerenza.`]},{heading:`Esegui un primo ordine con poche ipotesi`,paragraphs:[`Scegli un'opzione chiara, salva la scheda, valuta il QC prima di aggiungere e attendi i dati imballati prima di giudicare il trasporto.`],bullets:[`Opzioni chiare`,`Scheda e variante salvate`,`QC prima`,`Dati del pacco`,`Risultato consegnato documentato`]},{heading:`Un verdetto prudente`,paragraphs:[`Il resoconto è un segnale iniziale positivo per acquisto e magazzino, non una valutazione globale. Mancano ciclo internazionale e campione maggiore.`]}]}]};function y(e){return e===`en`?d:d.map((t,n)=>{let r=v[e][n];return{...t,..._[e][n],intro:r.intro,visual:{eyebrow:r.visual.eyebrow,title:r.visual.title,caption:r.visual.caption,items:r.visual.items.map(([e,t])=>({label:e,text:t}))},sources:r.sources.map(([e,t])=>({label:e,note:t})),sections:r.sections}})}export{c as i,g as n,m as r,y as t};